const STORAGE_KEY = 'mairie_articles_db';

export const ArticleService = {
  getAll: (): Article[] => {
    try {
        const stored = localStorage.getItem(STORAGE_KEY);
        if (!stored) {
            localStorage.setItem(STORAGE_KEY, JSON.stringify(INITIAL_ARTICLES));
            return INITIAL_ARTICLES;
        }
        return JSON.parse(stored);
    } catch (e) {
        console.error("Erreur lecture articles", e);
        return INITIAL_ARTICLES;
    }
  },

  add: (article: Omit<Article, 'id' | 'date'>) => {
    const articles = ArticleService.getAll();
    const newArticle: Article = {
      ...article,
      id: Date.now(),
      date: new Date().toISOString().split('T')[0]
    };
    // Add new article at the beginning of the list
    const updated = [newArticle, ...articles];
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
    return newArticle;
  },

  reset: () => {
      localStorage.removeItem(STORAGE_KEY);
      window.location.reload();
  }
};

