}

export interface Dossier {
  id: string;
  type: string;
  status: 'En cours' | 'Validé' | 'Rejeté';
  date: string;
  description: string;
}

const USERS_KEY = 'mairie_users_db';
const CURRENT_USER_KEY = 'mairie_current_user';
const DOSSIERS_KEY = 'mairie_dossiers_db';

// Données simulées pour l'historique
const MOCK_DOSSIERS: Dossier[] = [
  { id: 'DOS-2023-001', type: 'Acte de naissance', status: 'Validé', date: '2023-10-01', description: 'Demande de copie intégrale' },
  { id: 'DOS-2023-004', type: 'Permis de construire', status: 'En cours', date: '2023-11-12', description: 'Extension maison individuelle' },
];

export const AuthService = {
  // Inscription
  register: (user: Omit<User, 'id'>) => {
    const users = JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
    const existingUser = users.find((u: User) => u.email === user.email);

    if (existingUser) {
      throw new Error("Cet email est déjà utilisé.");
    }

    const newUser = { ...user, id: Date.now().toString() };
    users.push(newUser);
    localStorage.setItem(USERS_KEY, JSON.stringify(users));

    // Auto login
    AuthService.login(user.email, user.password || '');

    // Init mock history for new user
    const allDossiers = JSON.parse(localStorage.getItem(DOSSIERS_KEY) || '{}');
    allDossiers[newUser.id] = [];
    localStorage.setItem(DOSSIERS_KEY, JSON.stringify(allDossiers));

    return newUser;
  },

  // Connexion
  login: (email: string, pass: string) => {
    const users = JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
    const user = users.find((u: User) => u.email === email && u.password === pass);

    if (!user) {
      throw new Error("Email ou mot de passe incorrect.");
    }

    const { password, ...safeUser } = user;
    localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(safeUser));
    return safeUser;
  },

  // Déconnexion
  logout: () => {
    localStorage.removeItem(CURRENT_USER_KEY);
    window.location.href = '/'; // Redirection simple
  },

  // Récupérer l'utilisateur courant
  getCurrentUser: (): User | null => {
    const stored = localStorage.getItem(CURRENT_USER_KEY);
    return stored ? JSON.parse(stored) : null;
  },

  // Récupérer l'historique des dossiers (sites/démarches)
  getHistory: (): Dossier[] => {
    const user = AuthService.getCurrentUser();
    if (!user) return [];

    const allDossiers = JSON.parse(localStorage.getItem(DOSSIERS_KEY) || '{}');
    let userDossiers = allDossiers[user.id];

    // Si pas de dossiers, on injecte des faux pour la démo si c'est la première fois
    if (!userDossiers && user.email === 'demo@ziguinchor.sn') {
        userDossiers = MOCK_DOSSIERS;
    }

    return userDossiers || [];
  },

  // Créer un nouveau dossier (Simulation de "Créer un site")
  createDossier: (type: string, description: string) => {
    const user = AuthService.getCurrentUser();
    if (!user) return;

    const allDossiers = JSON.parse(localStorage.getItem(DOSSIERS_KEY) || '{}');
    const userDossiers = allDossiers[user.id] || [];

    const newDossier: Dossier = {
        id: `DOS-${new Date().getFullYear()}-${Math.floor(Math.random() * 1000)}`,
        type,
        status: 'En cours',
        date: new Date().toISOString().split('T')[0],
        description
    };

    allDossiers[user.id] = [newDossier, ...userDossiers];
    localStorage.setItem(DOSSIERS_KEY, JSON.stringify(allDossiers));
    return newDossier;
  },

  // Exporter les données (Sauvegarde)
  exportData: () => {
    const user = AuthService.getCurrentUser();
    const history = AuthService.getHistory();

    const data = {
        userProfile: user,
        dossierHistory: history,
        exportDate: new Date().toISOString()
    };

    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(data, null, 2));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `mairie_export_${user?.name || 'citoyen'}.json`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  }
};

