import React, { useEffect, useState } from 'react';
import { AuthService, User, Dossier } from '../services/auth';
import { useNavigate, useLocation } from 'react-router-dom';
import { Download, PlusCircle, FileText, Settings, LogOut, Clock, CheckCircle, XCircle } from 'lucide-react';

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [user, setUser] = useState<User | null>(null);
  const [history, setHistory] = useState<Dossier[]>([]);
  const [showNewModal, setShowNewModal] = useState(false);
  const [newDossierType, setNewDossierType] = useState('Acte de naissance');

  useEffect(() => {
    const currentUser = AuthService.getCurrentUser();
    if (!currentUser) {
      navigate('/login');
      return;
    }
    setUser(currentUser);
    setHistory(AuthService.getHistory());

    // Check if we navigated here with an intent to create a specific dossier
    if (location.state && location.state.openNewDossier) {
        if (location.state.dossierType) {
            setNewDossierType(location.state.dossierType);
        }
        setShowNewModal(true);
        // Clean up state to prevent reopening on simple refresh (optional but good practice)
        window.history.replaceState({}, document.title);
    }
  }, [navigate, location]);

  const handleLogout = () => {
    AuthService.logout();
  };

  const handleExport = () => {
    AuthService.exportData();
  };

  const handleCreateDossier = () => {
    AuthService.createDossier(newDossierType, "Demande créée via l'Espace Citoyen");
    setHistory(AuthService.getHistory());
    setShowNewModal(false);
  };

  const getStatusBadge = (status: string) => {
      switch(status) {
          case 'Validé': return <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800"><CheckCircle className="w-3 h-3 mr-1"/> Validé</span>;
          case 'Rejeté': return <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-800"><XCircle className="w-3 h-3 mr-1"/> Rejeté</span>;
          default: return <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-yellow-100 text-yellow-800"><Clock className="w-3 h-3 mr-1"/> En cours</span>;
      }
  };

  if (!user) return null;

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-8">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Espace Citoyen</h1>
            <p className="mt-1 text-gray-600">Bienvenue, <span className="font-semibold text-primary">{user.name}</span></p>
          </div>
          <div className="mt-4 md:mt-0 flex space-x-3">
             <button onClick={handleExport} className="inline-flex items-center px-4 py-2 border border-gray-300 rounded-md shadow-sm text-sm font-medium text-gray-700 bg-white hover:bg-gray-50 focus:outline-none">
              <Download className="h-4 w-4 mr-2" />
              Exporter mes données
            </button>
            <button onClick={handleLogout} className="inline-flex items-center px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-red-600 hover:bg-red-700 focus:outline-none">
              <LogOut className="h-4 w-4 mr-2" />
              Déconnexion
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Profile Card */}
          <div className="bg-white shadow rounded-lg p-6 lg:col-span-1 h-fit">
            <div className="flex items-center space-x-4 mb-6">
              <div className="h-16 w-16 bg-primary rounded-full flex items-center justify-center text-white text-2xl font-bold">
                {user.name.charAt(0)}
              </div>
              <div>
                <h3 className="text-lg font-medium text-gray-900">Mon Profil</h3>
                <p className="text-sm text-gray-500">{user.email}</p>
              </div>
            </div>
            <div className="border-t border-gray-200 pt-4">
               <div className="py-2 flex justify-between">
                   <span className="text-sm text-gray-500">ID Citoyen</span>
                   <span className="text-sm font-medium text-gray-900">#{user.id.slice(-6)}</span>
               </div>
               <div className="py-2 flex justify-between">
                   <span className="text-sm text-gray-500">Statut</span>
                   <span className="text-sm font-medium text-green-600">Vérifié</span>
               </div>
               <button className="w-full mt-4 flex items-center justify-center px-4 py-2 border border-gray-300 rounded-md shadow-sm text-sm font-medium text-gray-700 bg-white hover:bg-gray-50">
                   <Settings className="h-4 w-4 mr-2" />
                   Modifier mes informations
               </button>
            </div>
