const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();

  // Check login status on mount and when location changes
  useEffect(() => {
    const user = AuthService.getCurrentUser();
    setIsLoggedIn(!!user);
  }, [location]);

  const navLinks = [
    { name: 'Accueil', path: '/' },
    { name: 'À propos', path: '/about' },
    { name: 'Conseil Municipal', path: '/conseil' },
    { name: 'Actualités', path: '/news' },
    { name: 'Agenda', path: '/agenda' },
    { name: 'Services', path: '/services' },
    { name: 'Documents', path: '/documents' },
    { name: 'Contact', path: '/contact' },
  ];

  const isActive = (path: string) => location.pathname === path;

  const handleAuthClick = () => {
    if (isLoggedIn) {
        navigate('/dashboard');
    } else {
        navigate('/login');
    }
  };

  return (
    <header className="bg-white shadow-md sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-20">
          {/* Logo Section */}
          <div className="flex items-center">
            <Link to="/" className="flex items-center space-x-3">
              <div className="bg-primary text-white p-2 rounded-lg">
                {/* Placeholder Logo Icon */}
                <svg className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
                </svg>
              </div>
              <div className="flex flex-col">
                <span className="text-xl font-bold text-gray-900 leading-none">Mairie de</span>
                <span className="text-lg font-semibold text-primary leading-none">Ziguinchor</span>
              </div>
            </Link>
          </div>

          {/* Desktop Navigation */}
          <div className="hidden lg:flex items-center space-x-1 xl:space-x-4">
            <nav className="flex space-x-1 xl:space-x-2">
              {navLinks.map((link) => (
                <Link
                  key={link.path}
                  to={link.path}
                  className={`px-2 py-2 rounded-md text-sm font-medium transition-colors whitespace-nowrap ${
                    isActive(link.path)
                      ? 'text-primary bg-green-50'
                      : 'text-gray-600 hover:text-primary hover:bg-gray-50'
                  }`}
                >
                  {link.name}
                </Link>
              ))}
            </nav>
            <div className="flex items-center space-x-3 border-l pl-4 border-gray-200">
                <button className="text-gray-500 hover:text-primary transition">
                    <Globe className="h-5 w-5" />
                </button>
                <button 
                    onClick={handleAuthClick}
                    className={`flex items-center space-x-2 px-4 py-2 rounded-md transition text-sm font-medium whitespace-nowrap ${isLoggedIn ? 'bg-green-100 text-primary hover:bg-green-200' : 'bg-primary text-white hover:bg-green-700'}`}
                >
                    <User className="h-4 w-4" />
                    <span>{isLoggedIn ? 'Mon Compte' : 'Espace Citoyen'}</span>
                </button>
            </div>
          </div>

          {/* Mobile menu button */}
          <div className="lg:hidden flex items-center">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="inline-flex items-center justify-center p-2 rounded-md text-gray-400 hover:text-gray-500 hover:bg-gray-100 focus:outline-none"
            >
              {isOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="lg:hidden bg-white border-t border-gray-100">
          <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3">
            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                onClick={() => setIsOpen(false)}
                className={`block px-3 py-2 rounded-md text-base font-medium ${
                  isActive(link.path)
                    ? 'text-primary bg-green-50'
                    : 'text-gray-600 hover:text-primary hover:bg-gray-50'
                }`}
              >
                {link.name}
              </Link>
            ))}
             <div className="mt-4 pt-4 border-t border-gray-100">
                <button 
                    onClick={() => { handleAuthClick(); setIsOpen(false); }}
                    className="w-full flex items-center justify-center space-x-2 bg-primary text-white px-4 py-2 rounded-md hover:bg-green-700 transition"
                >
                    <User className="h-4 w-4" />
                    <span>{isLoggedIn ? 'Mon Compte' : 'Espace Citoyen'}</span>
                </button>
            </div>
          </div>
        </div>
      )}
    </header>
  );
};

