const Signalement: React.FC = () => {
  const [formData, setFormData] = useState({
    type: 'Voirie',
    location: '',
    description: '',
    email: ''
  });
  const [isLocating, setIsLocating] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const handleLocate = () => {
    if (!navigator.geolocation) {
        alert("La géolocalisation n'est pas supportée par votre navigateur.");
        return;
    }
    setIsLocating(true);
    navigator.geolocation.getCurrentPosition(
        (position) => {
            const { latitude, longitude } = position.coords;
            // In a real app, we would reverse geocode this coordinates to an address
            setFormData(prev => ({...prev, location: `Lat: ${latitude.toFixed(4)}, Long: ${longitude.toFixed(4)}`}));
            setIsLocating(false);
        },
        () => {
            alert("Impossible de récupérer votre position.");
            setIsLocating(false);
        }
    );
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    ReportingService.submit(formData);
    setSubmitted(true);
    setFormData({ type: 'Voirie', location: '', description: '', email: '' });
  };

  if (submitted) {
      return (
          <div className="min-h-screen bg-gray-50 flex items-center justify-center p-4">
              <div className="bg-white rounded-2xl shadow-xl p-8 max-w-md w-full text-center">
                  <div className="mx-auto flex items-center justify-center h-16 w-16 rounded-full bg-green-100 mb-6">
                      <CheckCircle className="h-10 w-10 text-primary" />
                  </div>
                  <h2 className="text-2xl font-bold text-gray-900 mb-2">Signalement envoyé !</h2>
                  <p className="text-gray-600 mb-6">
                      Merci pour votre contribution citoyenne. Nos services techniques ont bien reçu votre signalement et interviendront dans les plus brefs délais.
                  </p>
                  <button 
                    onClick={() => setSubmitted(false)}
                    className="w-full bg-primary text-white py-2 px-4 rounded-lg font-medium hover:bg-green-700 transition"
                  >
                      Effectuer un autre signalement
                  </button>
              </div>
          </div>
      );
  }

  return (
    <div className="bg-white min-h-screen">
       {/* Hero */}
      <div className="bg-amber-500 py-12">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center text-white">
          <AlertTriangle className="h-12 w-12 mx-auto mb-4 text-white opacity-90" />
          <h1 className="text-4xl font-extrabold mb-2">Signalement d'incident</h1>
          <p className="text-amber-100 text-lg max-w-2xl mx-auto">
            Aidez-nous à améliorer la ville. Signalez les problèmes de voirie, d'éclairage ou de propreté directement aux services municipaux.
          </p>
        </div>
