                        </div>
                    </div>

                    <button 
                        type="submit"
                        className="w-full flex justify-center py-3 px-4 border border-transparent rounded-lg shadow-sm text-base font-bold text-white bg-amber-500 hover:bg-amber-600 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-amber-500 transition"
                    >
                        Envoyer le signalement
                    </button>
                </form>
            </div>

            {/* Map / Info */}
