                    />
                    <div className="absolute inset-0 bg-black/10 flex items-center justify-center pointer-events-none">
                        <span className="bg-white/90 px-4 py-2 rounded-full text-sm font-semibold shadow-md text-gray-800">
                            Carte interactive (Simulation)
                        </span>
                    </div>
                </div>

                <div className="bg-blue-50 border border-blue-100 rounded-xl p-6">
                    <h3 className="text-lg font-bold text-blue-800 mb-2">Comment ça marche ?</h3>
                    <ul className="space-y-3">
                        <li className="flex items-start">
                            <span className="flex-shrink-0 h-6 w-6 rounded-full bg-blue-200 text-blue-800 flex items-center justify-center text-xs font-bold mr-3">1</span>
                            <span className="text-blue-700 text-sm">Vous constatez un dysfonctionnement sur la voie publique.</span>
