                            <span className="text-blue-700 text-sm">Vous remplissez le formulaire avec une photo et la localisation.</span>
                        </li>
                        <li className="flex items-start">
                            <span className="flex-shrink-0 h-6 w-6 rounded-full bg-blue-200 text-blue-800 flex items-center justify-center text-xs font-bold mr-3">3</span>
                            <span className="text-blue-700 text-sm">Les services techniques reçoivent l'alerte et planifient l'intervention.</span>
                        </li>
                    </ul>
                </div>
            </div>

        </div>
      </div>
    </div>
  );
};

