  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('Tout');

  const categories = [
    { name: 'Tout', icon: null },
    { name: 'État Civil', icon: Baby },
    { name: 'Identité', icon: Users },
    { name: 'Urbanisme', icon: Home },
    { name: 'Famille', icon: Heart },
    { name: 'Professionnels', icon: Briefcase },
    { name: 'Cadre de vie', icon: HardHat },
  ];

  const procedures: Procedure[] = [
    { 
        title: "Acte de naissance", 
        category: "État Civil", 
        description: "Demande de copie intégrale ou d'extrait avec/sans filiation.", 
        icon: FileText,
        link: "/etat-civil" 
    },
    { 
        title: "Acte de mariage", 
        category: "État Civil", 
        description: "Obtenir une copie d'acte de mariage célébré à Ziguinchor.", 
        icon: FileText,
        link: "/etat-civil" 
    },
    { 
        title: "Acte de décès", 
