        category: "Identité", 
        description: "Prendre rendez-vous pour le dépôt ou le retrait de titres d'identité.", 
        icon: Users,
        link: "/contact" 
    },
    { 
        title: "Recensement citoyen", 
        category: "Identité", 
        description: "Obligatoire dès 16 ans pour la journée défense et citoyenneté.", 
        icon: Users,
        dossierType: "Recensement citoyen" 
    },
    { 
        title: "Permis de construire", 
        category: "Urbanisme", 
        description: "Demande pour maison individuelle ou annexe.", 
        icon: Home,
        dossierType: "Permis de construire" 
    },
    { 
        title: "Déclaration de travaux", 
