        dossierType: "Inscription scolaire" 
    },
    { 
        title: "Inscription crèche", 
        category: "Famille", 
        description: "Demande de place en crèche municipale.", 
        icon: Heart,
        dossierType: "Inscription crèche" 
    },
    { 
        title: "Signalement voirie", 
        category: "Cadre de vie", 
        description: "Signaler un nid de poule, un éclairage défectueux, etc.", 
        icon: HardHat,
        link: "/signalement" 
    },
    { 
        title: "Encombrants", 
        category: "Cadre de vie", 
        description: "Prendre rendez-vous pour le ramassage d'objets volumineux.", 
        icon: HardHat,
        link: "/contact" 
    },
    { 
        title: "Occupation domaine public", 
        category: "Professionnels", 
        description: "Terrasse, échafaudage, déménagement, benne.", 
        icon: Briefcase,
        dossierType: "Occupation domaine public" 
    },
    { 
        title: "Demande de subvention", 
        category: "Professionnels", 
        description: "Pour les associations : demande de financement annuel ou projet.", 
        icon: Briefcase,
        dossierType: "Demande de subvention" 
    }
  ];

  const handleProcedureClick = (proc: Procedure) => {
    if (proc.link) {
        navigate(proc.link);
    } else if (proc.dossierType) {
        const user = AuthService.getCurrentUser();
        if (user) {
            navigate('/dashboard', { state: { openNewDossier: true, dossierType: proc.dossierType } });
        } else {
            // Store intent in local storage or just redirect to login
            // For simplicity here, alert + redirect
            if(window.confirm("Cette démarche nécessite un compte Citoyen. Voulez-vous vous connecter ?")) {
                navigate('/login');
            }
        }
    }
  };

  const filteredProcedures = procedures.filter(proc => {
      const matchesSearch = proc.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            proc.description.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = selectedCategory === 'Tout' || proc.category === selectedCategory;
      return matchesSearch && matchesCategory;
  });

  return (
    <div className="bg-gray-50 min-h-screen">
      {/* Header */}
      <div className="bg-primary text-white py-16">
