            <input
              type="text"
              className="block w-full pl-10 pr-3 py-4 border-none rounded-xl leading-5 bg-white text-gray-900 placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-secondary shadow-lg text-lg"
              placeholder="Que souhaitez-vous faire ?"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">

        {/* Categories */}
        <div className="flex flex-wrap justify-center gap-3 mb-12">
            {categories.map((cat) => (
                <button
                    key={cat.name}
                    onClick={() => setSelectedCategory(cat.name)}
                    className={`flex items-center px-4 py-2 rounded-full text-sm font-medium transition duration-200 ${
                        selectedCategory === cat.name
                        ? 'bg-secondary text-gray-900 shadow-md'
                        : 'bg-white text-gray-600 border border-gray-200 hover:bg-gray-100'
                    }`}
                >
                    {cat.icon && <cat.icon className="h-4 w-4 mr-2" />}
                    {cat.name}
                </button>
            ))}
        </div>

        {/* Procedures Grid */}
        {filteredProcedures.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredProcedures.map((proc, idx) => (
                <div 
                    key={idx} 
                    onClick={() => handleProcedureClick(proc)}
                    className="bg-white rounded-xl shadow-sm hover:shadow-lg transition-shadow duration-300 p-6 border border-gray-100 cursor-pointer group"
                >
                    <div className="flex items-start justify-between mb-4">
                        <div className={`p-3 rounded-lg ${
                            proc.category === 'État Civil' ? 'bg-blue-50 text-blue-600' :
                            proc.category === 'Urbanisme' ? 'bg-orange-50 text-orange-600' :
                            proc.category === 'Identité' ? 'bg-purple-50 text-purple-600' :
                            'bg-green-50 text-primary'
                        }`}>
                            <proc.icon className="h-6 w-6" />
                        </div>
                        <ChevronRight className="h-5 w-5 text-gray-300 group-hover:text-primary transition" />
                    </div>
                    <div className="mb-2">
                        <span className="text-xs font-semibold uppercase tracking-wider text-gray-500">{proc.category}</span>
                        <h3 className="text-lg font-bold text-gray-900 mt-1 group-hover:text-primary transition">{proc.title}</h3>
                    </div>
                    <p className="text-gray-600 text-sm line-clamp-2">
                        {proc.description}
                    </p>
                </div>
            ))}
            </div>
        ) : (
            <div className="text-center py-16">
                <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-gray-100 mb-4">
                    <Search className="h-8 w-8 text-gray-400" />
                </div>
                <h3 className="text-lg font-medium text-gray-900">Aucun résultat trouvé</h3>
                <p className="text-gray-500 mt-1">Essayez de modifier votre recherche ou de changer de catégorie.</p>
                <button 
                    onClick={() => { setSearchTerm(''); setSelectedCategory('Tout'); }}
                    className="mt-4 text-primary hover:text-green-700 font-medium"
                >
                    Réinitialiser les filtres
                </button>
            </div>
        )}

      </div>
    </div>
  );
