import React, { useState, useRef, useEffect } from 'react';
import { MessageCircle, X, Send, Minimize2, User, HelpCircle } from 'lucide-react';

interface Message {
  id: number;
  text: string;
  sender: 'user' | 'bot';
  time: string;
}

const ChatWidget: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [isHovered, setIsHovered] = useState(false);
  const [inputValue, setInputValue] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 1,
      text: "Bonjour ! Je suis l'assistant virtuel de la Mairie de Ziguinchor. Comment puis-je vous aider aujourd'hui ?",
      sender: 'bot',
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    }
  ]);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isTyping, isOpen]);

  const handleSendMessage = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!inputValue.trim()) return;

    const newUserMsg: Message = {
      id: Date.now(),
      text: inputValue,
      sender: 'user',
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };

    setMessages(prev => [...prev, newUserMsg]);
    setInputValue('');
    setIsTyping(true);

    // Simulation de réponse du bot
    setTimeout(() => {
      const botResponse = getBotResponse(newUserMsg.text);
      const newBotMsg: Message = {
        id: Date.now() + 1,
        text: botResponse,
        sender: 'bot',
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      };
      setMessages(prev => [...prev, newBotMsg]);
      setIsTyping(false);
    }, 1500);
  };

  const getBotResponse = (input: string): string => {
    const lowerInput = input.toLowerCase();

    if (lowerInput.includes('bonjour') || lowerInput.includes('salut')) {
        return "Bonjour ! Ravi de vous voir sur notre site.";
    }
    if (lowerInput.includes('horaire') || lowerInput.includes('ouverture') || lowerInput.includes('fermeture')) {
        return "Nos bureaux sont ouverts du Lundi au Vendredi de 08h00 à 17h00, et le Samedi de 09h00 à 12h00.";
    }
    if (lowerInput.includes('acte') || lowerInput.includes('naissance') || lowerInput.includes('civil')) {
        return "Vous pouvez effectuer vos demandes d'actes d'état civil directement en ligne via la rubrique 'Services' ou 'État Civil' du menu.";
    }
    if (lowerInput.includes('maire') || lowerInput.includes('sonko')) {
        return "Le Maire de Ziguinchor est M. Ousmane Sonko. Vous pouvez consulter la rubrique 'Conseil' pour plus d'informations sur l'équipe municipale.";
    }
    if (lowerInput.includes('contact') || lowerInput.includes('telephone') || lowerInput.includes('mail')) {
        return "Vous pouvez nous joindre au +221 33 991 12 34 ou par email à contact@mairieziguinchor.sn.";
    }
    if (lowerInput.includes('adresse') || lowerInput.includes('localisation')) {
        return "L'Hôtel de Ville est situé Rue du Général de Gaulle à Ziguinchor.";
    }

    return "Je ne suis pas sûr de comprendre votre demande. Pour une assistance personnalisée, veuillez utiliser le formulaire de contact ou appeler nos services.";
  };

  return (
    <div className="fixed bottom-6 right-6 z-50 flex flex-col items-end font-sans">
      {/* Chat Window */}
      {isOpen && (
        <div className="bg-white w-80 sm:w-96 rounded-2xl shadow-2xl mb-4 border border-gray-200 overflow-hidden flex flex-col transition-all duration-300 animate-fade-in-up" style={{ height: '500px' }}>

          {/* Header */}
          <div className="bg-primary p-4 flex justify-between items-center text-white shadow-md">
            <div className="flex items-center space-x-2">
                <div className="relative">
                    <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center">
                        <HelpCircle className="w-6 h-6 text-white" />
                    </div>
                    <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-400 border-2 border-primary rounded-full"></div>
                </div>
                <div>
                    <h3 className="font-bold text-sm">Assistance Mairie</h3>
                    <p className="text-xs text-green-100">En ligne</p>
                </div>
            </div>
            <div className="flex space-x-2">
                <button onClick={() => setIsOpen(false)} className="hover:bg-white/20 p-1 rounded transition">
                    <Minimize2 className="w-5 h-5" />
                </button>
                <button onClick={() => setIsOpen(false)} className="hover:bg-white/20 p-1 rounded transition">
                    <X className="w-5 h-5" />
                </button>
            </div>
          </div>

          {/* Messages Area */}
          <div className="flex-1 overflow-y-auto p-4 bg-gray-50 space-y-4">
            <div className="text-center text-xs text-gray-400 my-2">Aujourd'hui</div>

            {messages.map((msg) => (
              <div 
                key={msg.id} 
                className={`flex w-full ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div className={`max-w-[80%] rounded-2xl px-4 py-2 text-sm shadow-sm ${
                  msg.sender === 'user' 
                    ? 'bg-primary text-white rounded-tr-none' 
                    : 'bg-white text-gray-800 border border-gray-100 rounded-tl-none'
                }`}>
                  <p>{msg.text}</p>
                  <p className={`text-[10px] mt-1 text-right ${msg.sender === 'user' ? 'text-green-100' : 'text-gray-400'}`}>
                    {msg.time}
                  </p>
                </div>
              </div>
            ))}

            {isTyping && (
               <div className="flex justify-start">
                   <div className="bg-white border border-gray-100 rounded-2xl rounded-tl-none px-4 py-3 shadow-sm flex items-center space-x-1">
                       <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                       <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                       <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
                   </div>
               </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <form onSubmit={handleSendMessage} className="p-3 bg-white border-t border-gray-100 flex items-center space-x-2">
            <input
              type="text"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              placeholder="Posez votre question..."
              className="flex-1 border border-gray-200 rounded-full px-4 py-2 text-sm focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary bg-gray-50"
            />
            <button 
                type="submit" 
                disabled={!inputValue.trim()}
                className={`p-2 rounded-full transition ${inputValue.trim() ? 'bg-primary text-white hover:bg-green-700 shadow-md' : 'bg-gray-200 text-gray-400'}`}
            >
                <Send className="w-5 h-5" />
            </button>
          </form>
        </div>
      )}

      {/* Toggle Button */}
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          onMouseEnter={() => setIsHovered(true)}
          onMouseLeave={() => setIsHovered(false)}
          className="bg-primary hover:bg-green-700 text-white p-4 rounded-full shadow-lg transition-all duration-300 transform hover:scale-110 flex items-center justify-center group relative"
        >
          <MessageCircle className="w-7 h-7" />

          {/* Notification Badge */}
          <span className="absolute top-0 right-0 -mt-1 -mr-1 w-4 h-4 bg-red-500 rounded-full border-2 border-white"></span>

          {/* Tooltip */}
          <div className={`absolute right-full mr-4 bg-gray-900 text-white text-xs px-3 py-1.5 rounded-lg whitespace-nowrap transition-opacity duration-300 ${isHovered ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}>
              Discuter avec nous
          </div>
        </button>
      )}
    </div>
  );
};

export default ChatWidget;

