import { db, Message } from './database';

export interface Article {
  id: number;
  title: string;
  category: string;
  content: string;
  imageUrl: string;
  date: string;
  isFeatured?: boolean;
}

export interface Event {
  id: number;
  title: string;
  category: string;
  description: string;
  imageUrl: string;
  date: string;
  time: string;
  location: string;
}

export interface CouncilMember {
  id: number;
  name: string;
  role: string;
  image: string;
  commission?: string;
}

export interface CouncilSession {
  id: number;
  date: string;
  title: string;
  status: 'A venir' | 'Passé';
  docUrl?: string;
}

export interface Report {
    id: number;
    type: string;
    location: string;
    description: string;
    date: string;
    status: 'Nouveau' | 'Pris en compte' | 'Résolu';
    email?: string;
}

export const ArticleService = {
  getAll: (): Article[] => {
    return db.getArticles();
  },

  getById: (id: number): Article | undefined => {
    return db.getArticles().find(a => a.id === id);
  },

  add: (article: Omit<Article, 'id' | 'date'>) => {
    const newArticle: Article = {
      ...article,
      id: Date.now(),
      date: new Date().toISOString().split('T')[0]
    };
    db.addArticle(newArticle);
    return newArticle;
  },

  reset: () => {
      db.reset();
  }
};

export const EventService = {
    getAll: (): Event[] => {
        return db.getEvents();
    },
    getById: (id: number): Event | undefined => {
        return db.getEvents().find(e => e.id === id);
    }
};

export const CouncilService = {
    getMembers: (): CouncilMember[] => db.getMembers(),
    getSessions: (): CouncilSession[] => db.getSessions()
};

export const ReportingService = {
    submit: (report: Omit<Report, 'id' | 'date' | 'status'>) => {
        const newReport: Report = {
            ...report,
            id: Date.now(),
            date: new Date().toISOString(),
            status: 'Nouveau'
        };
        db.addReport(newReport);
        return newReport;
    },
    getAll: (): Report[] => {
        return db.getReports();
    },
    updateStatus: (id: number, status: Report['status']) => {
        db.updateReportStatus(id, status);
    }
};

export const ContactService = {
    send: (msg: Omit<Message, 'id' | 'date' | 'status'>) => {
        const newMessage: Message = {
            ...msg,
            id: Date.now(),
            date: new Date().toISOString(),
            status: 'Nouveau'
        };
        db.addMessage(newMessage);
        return newMessage;
    },
    getAll: (): Message[] => {
        return db.getMessages();
    }
};

