  useEffect(() => {
    const user = AuthService.getCurrentUser();
    setIsLoggedIn(!!user);
    setIsAdmin(user?.role === 'admin');
  }, [location]);

  interface NavLink {
      name: string;
      path?: string;
      children?: { name: string; path: string }[];
  }

  const navLinks: NavLink[] = [
    { name: 'Accueil', path: '/' },
    { 
      name: 'La Mairie', 
      children: [
        { name: 'À propos', path: '/about' },
        { name: 'Conseil Municipal', path: '/conseil' },
        { name: 'Documents & Archives', path: '/documents' },
      ]
    },
    { 
      name: 'Services', 
      children: [
        { name: 'Vue d\'ensemble', path: '/services' },
        { name: 'État Civil', path: '/etat-civil' },
        { name: 'Urbanisme', path: '/urbanisme' },
        { name: 'Action Sociale', path: '/social' },
        { name: 'Environnement', path: '/environnement' },
        { name: 'Entreprises', path: '/entreprises' },
        { name: 'Tourisme', path: '/tourisme' },
