import React, { useState } from 'react';
import { AuthService } from '../services/auth';
import { useNavigate, Link } from 'react-router-dom';
import { LogIn, User, ShieldCheck } from 'lucide-react';

const Login: React.FC = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({ email: '', password: '' });
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const user = AuthService.login(formData.email, formData.password);
      window.dispatchEvent(new Event('storage')); // Force update navbar
      if (user.role === 'admin') {
          navigate('/admin');
      } else {
          navigate('/dashboard');
      }
    } catch (err: any) {
      setError(err.message);
    }
  };

  const handleQuickAdmin = () => {
      setFormData({ email: 'admin@mairie.sn', password: 'admin' });
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col justify-center py-12 sm:px-6 lg:px-8">
      <div className="sm:mx-auto sm:w-full sm:max-w-md">
        <div className="flex justify-center">
            <div className="h-12 w-12 bg-primary rounded-xl flex items-center justify-center text-white">
                <User className="h-6 w-6" />
            </div>
        </div>
        <h2 className="mt-6 text-center text-3xl font-extrabold text-gray-900">
          Connexion Espace Citoyen
        </h2>
        <p className="mt-2 text-center text-sm text-gray-600">
          Ou{' '}
          <Link to="/register" className="font-medium text-primary hover:text-green-500">
            créer un nouveau compte
          </Link>
        </p>
      </div>

      <div className="mt-8 sm:mx-auto sm:w-full sm:max-w-md">
        <div className="bg-white py-8 px-4 shadow sm:rounded-lg sm:px-10">
          {error && (
            <div className="bg-red-50 border-l-4 border-red-400 p-4 mb-4">
              <div className="flex">
                <div className="ml-3">
                  <p className="text-sm text-red-700">{error}</p>
                </div>
              </div>
            </div>
          )}

          <form className="space-y-6" onSubmit={handleSubmit}>
            <div>
              <label htmlFor="email" className="block text-sm font-medium text-gray-700">
                Adresse Email
              </label>
              <div className="mt-1">
                <input
                  id="email"
                  name="email"
                  type="email"
                  autoComplete="email"
                  required
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  className="appearance-none block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm placeholder-gray-400 focus:outline-none focus:ring-primary focus:border-primary sm:text-sm"
                />
              </div>
            </div>

            <div>
              <label htmlFor="password" className="block text-sm font-medium text-gray-700">
                Mot de passe
              </label>
              <div className="mt-1">
                <input
                  id="password"
                  name="password"
                  type="password"
                  autoComplete="current-password"
                  required
                  value={formData.password}
                  onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                  className="appearance-none block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm placeholder-gray-400 focus:outline-none focus:ring-primary focus:border-primary sm:text-sm"
                />
              </div>
            </div>

            <div className="space-y-3">
              <button
                type="submit"
                className="w-full flex justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-primary hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary"
              >
                <LogIn className="h-4 w-4 mr-2" />
                Se connecter
              </button>

              <button
                type="button"
                onClick={handleQuickAdmin}
                className="w-full flex justify-center py-2 px-4 border border-gray-300 rounded-md shadow-sm text-xs font-medium text-gray-500 bg-white hover:bg-gray-50 focus:outline-none"
              >
                <ShieldCheck className="h-4 w-4 mr-2" />
                Pré-remplir Admin (Test)
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Login;

{
  "name": "mairie-ziguinchor-api",
  "version": "1.0.0",
  "description": "API Backend pour le site de la Mairie de Ziguinchor",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "dev": "nodemon server.js"
  },
  "dependencies": {
    "express": "^4.18.2",
    "cors": "^2.8.5",
    "body-parser": "^1.20.2"
  },
  "devDependencies": {
    "nodemon": "^3.0.1"
  }
}

const express = require('express');
const cors = require('cors');
const bodyParser = require('body-parser');
const db = require('./db');

const app = express();
const PORT = 3001;

// Middleware
app.use(cors());
app.use(bodyParser.json());

// --- ROUTES ---

// Authentification
app.post('/api/auth/login', (req, res) => {
    try {
        const { email, password } = req.body;
        const user = db.findUserByEmail(email);
        if (!user || user.password !== password) {
            return res.status(401).json({ error: "Email ou mot de passe incorrect." });
        }
        const { password: _, ...safeUser } = user;
        res.json(safeUser);
    } catch (e) {
        res.status(500).json({ error: e.message });
    }
});

app.post('/api/auth/register', (req, res) => {
    try {
        const user = db.registerUser(req.body);
        const { password: _, ...safeUser } = user;
        res.json(safeUser);
    } catch (e) {
        res.status(400).json({ error: e.message });
    }
});

// Articles
app.get('/api/articles', (req, res) => {
    res.json(db.getArticles());
});

app.post('/api/articles', (req, res) => {
    // Dans un vrai cas, vérification admin ici
    const newArticle = db.addArticle(req.body);
    res.json(newArticle);
});

// Événements
app.get('/api/events', (req, res) => {
    res.json(db.getEvents());
});

// Conseil Municipal
app.get('/api/council/members', (req, res) => {
    res.json(db.getMembers());
});

app.get('/api/council/sessions', (req, res) => {
    res.json(db.getSessions());
});

// Signalements (Reports)
app.get('/api/reports', (req, res) => {
    res.json(db.getReports());
});

app.post('/api/reports', (req, res) => {
    const report = db.addReport(req.body);
    res.json(report);
});

app.put('/api/reports/:id/status', (req, res) => {
    const id = parseInt(req.params.id);
    const { status } = req.body;
    db.updateReportStatus(id, status);
    res.json({ success: true, id, status });
});

// Messages (Contact)
app.get('/api/messages', (req, res) => {
    res.json(db.getMessages());
});

app.post('/api/messages', (req, res) => {
    const msg = db.addMessage(req.body);
    res.json(msg);
});

// Dossiers Citoyens
app.get('/api/dossiers', (req, res) => {
    // Route Admin : tous les dossiers
    res.json(db.getAllDossiers());
});

app.get('/api/dossiers/user/:userId', (req, res) => {
    const { userId } = req.params;
    res.json(db.getUserDossiers(userId));
});

app.post('/api/dossiers', (req, res) => {
    const { userId, type, description } = req.body;
    const dossier = db.addDossier(userId, { type, description });
    res.json(dossier);
});

// Start Server
app.listen(PORT, () => {
    console.log(`Serveur Backend démarré sur http://localhost:${PORT}`);
    console.log(`API disponible sur http://localhost:${PORT}/api`);
});

