const express = require('express');
const router = express.Router();
const articleController = require('../controllers/articleController');
const multer = require('multer');
const path = require('path');
const fs = require('fs');

// Ensure uploads directory exists
const uploadDir = 'uploads/';
if (!fs.existsSync(uploadDir)){
    fs.mkdirSync(uploadDir);
}

// Configure Multer Storage
const storage = multer.diskStorage({
    destination: (req, file, cb) => {
        cb(null, uploadDir);
    },
    filename: (req, file, cb) => {
        cb(null, Date.now() + path.extname(file.originalname));
    }
});

const upload = multer({ storage: storage });

router.get('/', articleController.getAll);

// 'image' is the field name in the form-data
router.post('/', upload.single('image'), articleController.create);

// Route spéciale pour reset la DB (dev only)
router.post('/reset', articleController.reset);

module.exports = router;

const Article = require('../models/Article');

exports.getAll = (req, res) => {
    res.json(Article.findAll());
};

exports.create = (req, res) => {
    let imageUrl = req.body.imageUrl;

    // Check if a file was uploaded via Multer
    if (req.file) {
        const protocol = req.protocol;
        const host = req.get('host');
        // Construct the full URL to the uploaded file
        imageUrl = `${protocol}://${host}/uploads/${req.file.filename}`;
    }

    const articleData = {
        ...req.body,
        imageUrl: imageUrl || 'https://picsum.photos/800/600' // Default/Fallback
    };

    const newArticle = Article.create(articleData);
    res.json(newArticle);
};

exports.reset = (req, res) => {
    Article.reset();
    res.json({ success: true, message: "Database reset" });
};

