const News: React.FC = () => {
  const [articles, setArticles] = useState<Article[]>([]);
  const [activeCategory, setActiveCategory] = useState("Tout");
  const categories = ["Tout", "Politique", "Culture", "Sport", "Urbanisme", "Santé", "Éducation"];
  const navigate = useNavigate();

  useEffect(() => {
      // Fetch articles from backend
      ArticleService.getAll().then(setArticles).catch(console.error);
  }, []);

  // Filter articles
  const filteredArticles = activeCategory === "Tout" 
    ? articles 
    : articles.filter(a => a.category === activeCategory);

  // Determine Featured Article (First one marked isFeatured, or just the first one if none)
  const featuredArticle = filteredArticles.find(a => a.isFeatured) || filteredArticles[0];
  // The rest of the list (excluding the featured one if it exists in the list)
  const standardArticles = filteredArticles.filter(a => a.id !== featuredArticle?.id);

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-extrabold text-gray-900 mb-4">Actualités et Événements</h1>
