const Admin: React.FC = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'overview' | 'articles' | 'reports' | 'messages' | 'dossiers'>('overview');

  // Data State
  const [reports, setReports] = useState<Report[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);
  const [dossiers, setDossiers] = useState<any[]>([]);
  const [articles, setArticles] = useState<any[]>([]);
  const [stats, setStats] = useState({
      pendingReports: 0,
      unreadMessages: 0,
      pendingDossiers: 0,
      totalUsers: 0
  });

  // Article Form State
  const [formData, setFormData] = useState({
    title: '',
    category: 'Actualité',
    content: '',
    imageUrl: 'https://picsum.photos/800/600',
    isFeatured: false
  });

  useEffect(() => {
      // Check admin rights
      const user = AuthService.getCurrentUser();
      if (!user || user.role !== 'admin') {
          navigate('/login');
          return;
      }

      refreshData();
  }, [activeTab, navigate]);

  const refreshData = async () => {
      const allReports = await ReportingService.getAll();
      const allMessages = await ContactService.getAll();
      const allDossiers = db.getAllDossiers();
      const allUsers = db.getUsers();
      const allArticles = await ArticleService.getAll();

      setReports(allReports);
      setMessages(allMessages);
      setDossiers(allDossiers);
      setArticles(allArticles);

      setStats({
          pendingReports: allReports.filter(r => r.status === 'Nouveau').length,
          unreadMessages: allMessages.filter(m => m.status === 'Nouveau').length,
          pendingDossiers: allDossiers.filter(d => d.status === 'En cours').length,
          totalUsers: allUsers.length
      });
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];

          // Since we are using a mock DB service in the frontend for now,
          // we convert the file to Base64 to store it as a string.
          // In a real API integration, we would append 'file' to a FormData object.
          const reader = new FileReader();
          reader.onloadend = () => {
              setFormData({ ...formData, imageUrl: reader.result as string });
          };
          reader.readAsDataURL(file);
      }
  };

  const handleSubmitArticle = async (e: React.FormEvent) => {
    e.preventDefault();
    await ArticleService.add(formData);
