};

export const ContactService = {
    send: async (msg: Omit<Message, 'id' | 'date' | 'status'>) => {
        const res = await fetch(`${API_URL}/messages`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(msg)
        });
        return res.json();
    },
    getAll: async (): Promise<Message[]> => {
        const res = await fetch(`${API_URL}/messages`);
        return res.json();
    }
};

