        (position) => {
            const { latitude, longitude } = position.coords;
            // In a real app, we would reverse geocode this coordinates to an address
            setFormData(prev => ({...prev, location: `Lat: ${latitude.toFixed(4)}, Long: ${longitude.toFixed(4)}`}));
