        return rows;
    }

    static async getDocuments() {
        const [rows] = await db.query('SELECT * FROM documents');
        return rows;
    }

    static async addDocument(data) {
        const { name, type, size, category } = data;
        const [result] = await db.query(
            'INSERT INTO documents (name, type, size, category) VALUES (?, ?, ?, ?)',
            [name, type, size, category]
        );
        return { id: result.insertId, ...data };
    }

    static async deleteDocument(id) {
        const [result] = await db.query('DELETE FROM documents WHERE id = ?', [id]);
        return result.affectedRows > 0;
    }

    static async getProcedures() {
        const [rows] = await db.query('SELECT * FROM procedures_list');
        return rows;
    }

    static async getProjects() {
        const [rows] = await db.query('SELECT * FROM projects');
        return rows;
    }

    static async getNeighborhoods() {
        const [rows] = await db.query('SELECT * FROM neighborhoods');
        return rows;
    }

    static async updateNeighborhood(id, data) {
        const { representative, nextMeeting } = data;
        const [result] = await db.query(
            'UPDATE neighborhoods SET representative = ?, nextMeeting = ? WHERE id = ?',
            [representative, nextMeeting, id]
        );
        return result.affectedRows > 0;
    }
}

