        const articlesResponse = await ArticleService.getAll(1, 1000);
        const councilResponse = await CouncilService.getMembers();
        const hoodsResponse = await ContentService.getNeighborhoods();
        const docsResponse = await ContentService.getDocuments();

        setReports(allReports);
        setMessages(allMessages);
        setDossiers(allDossiers);
        setArticles(articlesResponse.data);
        setMembers(councilResponse);
        setNeighborhoods(hoodsResponse);
        setDocuments(docsResponse);

        setStats({
            pendingReports: allReports.filter(r => r.status === 'Nouveau').length,
            unreadMessages: allMessages.filter(m => m.status === 'Nouveau').length,
            pendingDossiers: allDossiers.filter(d => d.status === 'En cours').length,
