// --- Services using Fetch ---

export const ContentService = {
    getServices: async (): Promise<ServiceItem[]> => {
        const res = await fetch(`${API_URL}/content/services`);
        return res.json();
    },
    getDocuments: async (): Promise<DocumentItem[]> => {
        const res = await fetch(`${API_URL}/content/documents`);
        return res.json();
    },
    addDocument: async (doc: DocumentItem) => {
        const res = await fetch(`${API_URL}/content/documents`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(doc)
        });
        return res.json();
    },
    deleteDocument: async (id: number) => {
        await fetch(`${API_URL}/content/documents/${id}`, { method: 'DELETE' });
    },
    getProcedures: async (): Promise<ProcedureItem[]> => {
        const res = await fetch(`${API_URL}/content/procedures`);
        return res.json();
    },
    getProjects: async (): Promise<ProjectItem[]> => {
        const res = await fetch(`${API_URL}/content/projects`);
        return res.json();
    },
    getNeighborhoods: async (): Promise<Neighborhood[]> => {
        const res = await fetch(`${API_URL}/content/neighborhoods`);
        return res.json();
    },
    updateNeighborhood: async (id: number, data: Partial<Neighborhood>) => {
        await fetch(`${API_URL}/content/neighborhoods/${id}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(data)
        });
    },
    getAbout: async (): Promise<AboutSection[]> => {
        const res = await fetch(`${API_URL}/content/about`);
        return res.json();
    },
    updateAbout: async (id: number, content: string) => {
        await fetch(`${API_URL}/content/about/${id}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ content })
        });
    }
};

export const ArticleService = {
  getAll: async (page = 1, limit = 9, category = 'Tout'): Promise<PaginatedArticles> => {
    const url = new URL(`${API_URL}/articles`);
    url.searchParams.append('page', page.toString());
    url.searchParams.append('limit', limit.toString());
    if (category && category !== 'Tout') {
        url.searchParams.append('category', category);
    }

    const res = await fetch(url.toString());
    return res.json();
  },

  getById: async (id: number): Promise<Article | undefined> => {
    const res = await fetch(`${API_URL}/articles/${id}`);
    if (!res.ok) return undefined;
    return res.json();
  },

  add: async (article: Omit<Article, 'id' | 'date'>) => {
    const res = await fetch(`${API_URL}/articles`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(article)
    });
    return res.json();
  },

  reset: async () => {
      await fetch(`${API_URL}/articles/reset`, { method: 'POST' });
      window.location.reload();
  }
};

