            throw new Error(err.error || 'Erreur d\'inscription');
        }
        return res.json();
    }
};

import React, { useState, useEffect } from 'react';
import { 
    ArticleService, ReportingService, ContactService, Report, DossierService, UserService, Message, 
    CouncilService, ContentService, EventService, CouncilMember, Neighborhood, DocumentItem, Event as EventType, AboutSection
} from '../services/api';
