  const refreshData = async () => {
      try {
        const allReports = await ReportingService.getAll();
        const allMessages = await ContactService.getAll();
        const allDossiers = await DossierService.getAll();
        const allUsers = await UserService.getAll();

        const articlesResponse = await ArticleService.getAll(1, 1000);
        const councilResponse = await CouncilService.getMembers();
        const hoodsResponse = await ContentService.getNeighborhoods();
        const docsResponse = await ContentService.getDocuments();
        const eventsResponse = await EventService.getAll();
        const aboutResponse = await ContentService.getAbout();

        setReports(allReports);
        setMessages(allMessages);
        setDossiers(allDossiers);
        setArticles(articlesResponse.data);
        setMembers(councilResponse);
        setNeighborhoods(hoodsResponse);
        setDocuments(docsResponse);
        setEvents(eventsResponse);
        setAboutSections(aboutResponse);

        setStats({
            pendingReports: allReports.filter(r => r.status === 'Nouveau').length,
            unreadMessages: allMessages.filter(m => m.status === 'Nouveau').length,
            pendingDossiers: allDossiers.filter(d => d.status === 'En cours').length,
            totalUsers: allUsers.length
        });
      } catch (err) {
        console.error("Erreur chargement données admin", err);
      }
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>, formSetter: any, currentData: any) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          const reader = new FileReader();
          reader.onloadend = () => {
              formSetter({ ...currentData, imageUrl: reader.result as string });
          };
          reader.readAsDataURL(file);
      }
  };

