      e.preventDefault();
      await CouncilService.addMember(memberFormData);
      alert('Membre ajouté');
      setMemberFormData({ name: '', role: 'Conseiller', image: 'https://picsum.photos/300/300', commission: '' });
      refreshData();
  };

  const handleDeleteMember = async (id: number) => {
      if(window.confirm('Supprimer ce membre ?')) {
          await CouncilService.deleteMember(id);
          refreshData();
      }
  };

  const handleSubmitDocument = async (e: React.FormEvent) => {
