                </div>
                <nav className="flex flex-col p-2 space-y-1">
                    <button onClick={() => setActiveTab('overview')} className={`px-4 py-3 text-left font-medium flex items-center rounded-lg transition-colors ${activeTab === 'overview' ? 'bg-primary text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}>
                        <LayoutDashboard className="h-5 w-5 mr-3" /> Vue d'ensemble
                    </button>

                    <div className="my-2 px-4 text-xs font-semibold text-gray-400 uppercase">Gestion</div>

                    <button onClick={() => setActiveTab('articles')} className={`px-4 py-3 text-left font-medium flex items-center rounded-lg transition-colors ${activeTab === 'articles' ? 'bg-primary text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}>
                        <Plus className="h-5 w-5 mr-3" /> Actualités
