                    <button onClick={() => setActiveTab('agenda')} className={`px-4 py-3 text-left font-medium flex items-center rounded-lg transition-colors ${activeTab === 'agenda' ? 'bg-primary text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}>
