const db = require('../db');

class Article {
    static async findAll(limit, offset, category) {
        let query = 'SELECT * FROM articles';
        let countQuery = 'SELECT COUNT(*) as total FROM articles';
        let params = [];
        let countParams = [];

        if (category && category !== 'Tout') {
            query += ' WHERE category = ?';
            countQuery += ' WHERE category = ?';
            params.push(category);
            countParams.push(category);
        }

        query += ' ORDER BY date DESC LIMIT ? OFFSET ?';
        params.push(limit, offset);

        const [rows] = await db.query(query, params);
        const [countResult] = await db.query(countQuery, countParams);
        const total = countResult[0].total;

        return {
            data: rows,
            meta: {
                total,
                page: (offset / limit) + 1,
                limit,
                totalPages: Math.ceil(total / limit)
            }
        };
    }

    static async findById(id) {
        const [rows] = await db.query('SELECT * FROM articles WHERE id = ?', [id]);
        return rows[0];
    }

    static async create(articleData) {
        const { title, category, content, imageUrl, isFeatured } = articleData;
        const date = new Date().toISOString().split('T')[0];

        const [result] = await db.query(
            'INSERT INTO articles (title, category, content, imageUrl, date, isFeatured) VALUES (?, ?, ?, ?, ?, ?)',
            [title, category, content, imageUrl, date, isFeatured ? 1 : 0]
        );

        return { id: result.insertId, ...articleData, date };
    }

    static async update(id, articleData) {
        const { title, category, content, imageUrl, isFeatured } = articleData;

        const [result] = await db.query(
            'UPDATE articles SET title = ?, category = ?, content = ?, imageUrl = ?, isFeatured = ? WHERE id = ?',
            [title, category, content, imageUrl, isFeatured ? 1 : 0, id]
        );

        return result.affectedRows > 0;
    }

    static async delete(id) {
        const [result] = await db.query('DELETE FROM articles WHERE id = ?', [id]);
        return result.affectedRows > 0;
    }

    static async reset() {
        await db.query('TRUNCATE TABLE articles');
        // Optionnel : Re-seed si nécessaire
    }
}

module.exports = Article;

const Article = require('../models/Article');

exports.getAll = async (req, res) => {
    try {
        let { page, limit, category } = req.query;
        page = parseInt(page) || 1;
        limit = parseInt(limit) || 9;
        const offset = (page - 1) * limit;

        // Appel au modèle qui gère la requête SQL
        const result = await Article.findAll(limit, offset, category);

        res.json(result);
    } catch (err) {
        console.error(err);
        res.status(500).json({ error: "Erreur lors de la récupération des articles" });
    }
};

exports.getById = async (req, res) => {
    try {
        const id = parseInt(req.params.id);
        const article = await Article.findById(id);

        if (article) {
            res.json(article);
        } else {
            res.status(404).json({ message: "Article non trouvé" });
        }
    } catch (err) {
        console.error(err);
        res.status(500).json({ error: "Erreur serveur" });
    }
};

exports.create = async (req, res) => {
    try {
        let imageUrl = req.body.imageUrl;

        if (req.file) {
            const protocol = req.protocol;
            const host = req.get('host');
            imageUrl = `${protocol}://${host}/uploads/${req.file.filename}`;
        }

        const articleData = {
            ...req.body,
            imageUrl: imageUrl || 'https://picsum.photos/800/600'
        };

        const newArticle = await Article.create(articleData);
        res.json(newArticle);
    } catch (err) {
        console.error(err);
        res.status(500).json({ error: "Erreur lors de la création de l'article" });
    }
};

exports.update = async (req, res) => {
    try {
        const id = parseInt(req.params.id);
        let imageUrl = req.body.imageUrl;

        if (req.file) {
            const protocol = req.protocol;
            const host = req.get('host');
            imageUrl = `${protocol}://${host}/uploads/${req.file.filename}`;
        }

        const articleData = {
            ...req.body,
            imageUrl: imageUrl // Garde l'ancienne URL si pas de nouvelle image uploadée
        };

        const success = await Article.update(id, articleData);
        if (success) {
            res.json({ success: true, ...articleData, id });
        } else {
            res.status(404).json({ error: "Article non trouvé" });
        }
    } catch (err) {
        console.error(err);
        res.status(500).json({ error: "Erreur lors de la mise à jour" });
    }
};

exports.delete = async (req, res) => {
