            body: JSON.stringify({ status })
        });
    }
};

export const ContactService = {
    send: async (msg: Omit<Message, 'id' | 'date' | 'status'>) => {
        const res = await fetch(`${API_URL}/messages`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(msg)
        });
        return res.json();
    },
    getAll: async (): Promise<Message[]> => {
        const res = await fetch(`${API_URL}/messages`);
        return res.json();
    }
};

export const DossierService = {
    getAll: async (): Promise<any[]> => {
        const res = await fetch(`${API_URL}/dossiers`);
        return res.json();
    },
    getByUser: async (userId: string): Promise<any[]> => {
        const res = await fetch(`${API_URL}/dossiers/user/${userId}`);
        return res.json();
    },
    create: async (dossierData: {userId: string, type: string, description: string}) => {
        const res = await fetch(`${API_URL}/dossiers`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(dossierData)
        });
        return res.json();
    }
};

export const UserService = {
    getAll: async (): Promise<any[]> => {
        const res = await fetch(`${API_URL}/auth/users`);
        return res.json();
    },
    login: async (credentials: any) => {
        const res = await fetch(`${API_URL}/auth/login`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(credentials)
        });
        if (!res.ok) {
            const err = await res.json();
            throw new Error(err.error || 'Erreur de connexion');
        }
        return res.json();
    },
    register: async (userData: any) => {
        const res = await fetch(`${API_URL}/auth/register`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(userData)
        });
        if (!res.ok) {
            const err = await res.json();
            throw new Error(err.error || 'Erreur d\'inscription');
        }
        return res.json();
    }
};

