const db = require('../db');

class Dossier {
    static async findAll() {
        // Jointure pour récupérer le nom de l'utilisateur si possible, sinon on le fera en front
        const [rows] = await db.query(`
            SELECT d.*, u.name as user_name, u.email as user_email 
            FROM dossiers d 
            LEFT JOIN users u ON d.user_id = u.id 
            ORDER BY d.date DESC
        `);
        return rows;
    }

    static async findByUserId(userId) {
        const [rows] = await db.query('SELECT * FROM dossiers WHERE user_id = ? ORDER BY date DESC', [userId]);
        return rows;
    }

    static async create(userId, dossierData) {
        const { type, description } = dossierData;
        // Génération d'un ID lisible type DOS-YYYY-XXXX
        const readableId = `DOS-${new Date().getFullYear()}-${Math.floor(Math.random() * 10000)}`;
        const date = new Date().toISOString().split('T')[0];
        const status = 'En cours';

        const [result] = await db.query(
            'INSERT INTO dossiers (id, user_id, type, description, date, status) VALUES (?, ?, ?, ?, ?, ?)',
            [readableId, userId, type, description, date, status]
        );

        return { id: readableId, userId, type, description, date, status };
    }

    static async updateStatus(id, status) {
        const [result] = await db.query('UPDATE dossiers SET status = ? WHERE id = ?', [status, id]);
        return result.affectedRows > 0;
    }

    static async delete(id) {
        const [result] = await db.query('DELETE FROM dossiers WHERE id = ?', [id]);
        return result.affectedRows > 0;
    }
}

module.exports = Dossier;

