            throw new Error(err.error || 'Erreur d\'inscription');
        }
        return res.json();
    }
};

import React, { useState, useEffect } from 'react';
import { 
    ArticleService, ReportingService, ContactService, Report, DossierService, UserService, Message, 
    CouncilService, ContentService, EventService, CouncilMember, Neighborhood, DocumentItem, Event as EventType, AboutSection, Article, CouncilSession
} from '../services/api';
import { useNavigate } from 'react-router-dom';
import { 
    Plus, Save, ArrowLeft, RefreshCw, LayoutDashboard, MessageSquare, AlertTriangle, 
    FileText, Check, Users, Search, Image as ImageIcon, Map, Trash2, Edit, Calendar, Info, X, Clock, CheckCircle, XCircle
} from 'lucide-react';
import { AuthService } from '../services/auth';

const Admin: React.FC = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'overview' | 'articles' | 'reports' | 'messages' | 'dossiers' | 'council' | 'neighborhoods' | 'documents' | 'agenda' | 'about'>('overview');

  // Data State
  const [reports, setReports] = useState<Report[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);
  const [dossiers, setDossiers] = useState<any[]>([]);
  const [articles, setArticles] = useState<Article[]>([]);
  const [members, setMembers] = useState<CouncilMember[]>([]);
  const [sessions, setSessions] = useState<CouncilSession[]>([]);
  const [neighborhoods, setNeighborhoods] = useState<Neighborhood[]>([]);
  const [documents, setDocuments] = useState<DocumentItem[]>([]);
  const [events, setEvents] = useState<EventType[]>([]);
  const [aboutSections, setAboutSections] = useState<AboutSection[]>([]);

  const [stats, setStats] = useState({
      pendingReports: 0,
      unreadMessages: 0,
      pendingDossiers: 0,
      totalUsers: 0
  });

  // --- Article Forms ---
  const [articleFormData, setArticleFormData] = useState({
    title: '',
    category: 'Actualité',
    content: '',
    imageUrl: 'https://picsum.photos/800/600',
    isFeatured: false
  });
  const [editingArticleId, setEditingArticleId] = useState<number | null>(null);

  // --- Member Forms ---
  const [memberFormData, setMemberFormData] = useState({
      name: '',
      role: 'Conseiller',
      image: 'https://picsum.photos/300/300',
      commission: ''
  });
  const [editingMemberId, setEditingMemberId] = useState<number | null>(null);

  // --- Session Forms ---
  const [sessionFormData, setSessionFormData] = useState<Partial<CouncilSession>>({
      title: '',
      date: '',
      status: 'A venir',
      docUrl: ''
  });
  const [editingSessionId, setEditingSessionId] = useState<number | null>(null);

  // --- Document Forms ---
  const [documentFormData, setDocumentFormData] = useState({
      name: '',
      category: 'Délibérations',
      type: 'PDF',
      size: '1.2 Mo'
  });
  const [editingDocumentId, setEditingDocumentId] = useState<number | null>(null);

  // --- Neighborhood Forms ---
  const [neighborhoodFormData, setNeighborhoodFormData] = useState<Partial<Neighborhood>>({
      name: '',
      representative: '',
      nextMeeting: '',
      location: '',
      description: ''
  });
  const [editingNeighborhoodId, setEditingNeighborhoodId] = useState<number | null>(null);

  // --- Event Forms ---
  const [eventFormData, setEventFormData] = useState({
      title: '',
      category: 'Culture',
      description: '',
      imageUrl: 'https://picsum.photos/800/600',
      date: '',
      time: '',
      location: ''
  });
  const [editingEventId, setEditingEventId] = useState<number | null>(null);

  // --- About Forms ---
  const [aboutFormData, setAboutFormData] = useState({
      title: '',
      content: ''
  });
  const [editingAboutId, setEditingAboutId] = useState<number | null>(null);

  useEffect(() => {
      const user = AuthService.getCurrentUser();
      if (!user || user.role !== 'admin') {
          navigate('/login');
          return;
      }
      refreshData();
  }, [activeTab, navigate]);

  const refreshData = async () => {
      try {
        const allReports = await ReportingService.getAll();
        const allMessages = await ContactService.getAll();
        const allDossiers = await DossierService.getAll();
        const allUsers = await UserService.getAll();

        const articlesResponse = await ArticleService.getAll(1, 1000);
        const councilMembers = await CouncilService.getMembers();
        const councilSessions = await CouncilService.getSessions();
        const hoodsResponse = await ContentService.getNeighborhoods();
        const docsResponse = await ContentService.getDocuments();
        const eventsResponse = await EventService.getAll();
        const aboutResponse = await ContentService.getAbout();

        setReports(allReports);
        setMessages(allMessages);
        setDossiers(allDossiers);
        setArticles(articlesResponse.data);
        setMembers(councilMembers);
        setSessions(councilSessions);
        setNeighborhoods(hoodsResponse);
        setDocuments(docsResponse);
        setEvents(eventsResponse);
        setAboutSections(aboutResponse);

        setStats({
            pendingReports: allReports.filter(r => r.status === 'Nouveau').length,
            unreadMessages: allMessages.filter(m => m.status === 'Nouveau').length,
            pendingDossiers: allDossiers.filter(d => d.status === 'En cours').length,
            totalUsers: allUsers.length
        });
      } catch (err) {
        console.error("Erreur chargement données admin", err);
      }
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>, formSetter: any, currentData: any) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          const reader = new FileReader();
          reader.onloadend = () => {
              formSetter({ ...currentData, imageUrl: reader.result as string });
          };
          reader.readAsDataURL(file);
      }
  };

  // --- Article Handlers ---
  const handleSubmitArticle = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingArticleId) {
        await ArticleService.update(editingArticleId, articleFormData);
        alert('Article modifié avec succès !');
    } else {
        await ArticleService.add(articleFormData);
        alert('Article publié avec succès !');
    }
    setArticleFormData({ title: '', category: 'Actualité', content: '', imageUrl: 'https://picsum.photos/800/600', isFeatured: false });
    setEditingArticleId(null);
    refreshData();
  };

  const handleEditArticle = (article: Article) => {
      setEditingArticleId(article.id);
      setArticleFormData({
          title: article.title,
          category: article.category,
          content: article.content,
          imageUrl: article.imageUrl,
          isFeatured: article.isFeatured || false
