      setEditingMemberId(null);
      setMemberFormData({ name: '', role: 'Conseiller', image: 'https://picsum.photos/300/300', commission: '' });
  };

  const handleDeleteMember = async (id: number) => {
      if(window.confirm('Supprimer ce membre ?')) {
          await CouncilService.deleteMember(id);
          refreshData();
      }
  };

  // --- Council Session Handlers ---
  const handleSubmitSession = async (e: React.FormEvent) => {
      e.preventDefault();
      if (editingSessionId) {
          await CouncilService.updateSession(editingSessionId, sessionFormData);
      } else {
          await CouncilService.addSession(sessionFormData as any);
      }
      setSessionFormData({ title: '', date: '', status: 'A venir', docUrl: '' });
      setEditingSessionId(null);
      refreshData();
  };

  const handleEditSession = (session: CouncilSession) => {
      setEditingSessionId(session.id);
      setSessionFormData({
          title: session.title,
          date: session.date,
          status: session.status,
          docUrl: session.docUrl || ''
      });
  };

  const handleDeleteSession = async (id: number) => {
      if(window.confirm('Supprimer cette séance ?')) {
          await CouncilService.deleteSession(id);
          refreshData();
      }
  };

  // --- Document Handlers ---
  const handleSubmitDocument = async (e: React.FormEvent) => {
      e.preventDefault();
      if (editingDocumentId) {
          await ContentService.updateDocument(editingDocumentId, documentFormData);
          alert('Document mis à jour');
      } else {
          await ContentService.addDocument(documentFormData);
          alert('Document ajouté');
      }
      setDocumentFormData({ name: '', category: 'Délibérations', type: 'PDF', size: '1.2 Mo' });
      setEditingDocumentId(null);
      refreshData();
  };

  const handleEditDocument = (doc: DocumentItem) => {
      if (doc.id) {
          setEditingDocumentId(doc.id);
          setDocumentFormData({
              name: doc.name,
              category: doc.category,
              type: doc.type,
              size: doc.size
          });
      }
  };

  const handleDeleteDocument = async (id: number) => {
      if(window.confirm('Supprimer ce document ?')) {
        if(id) await ContentService.deleteDocument(id);
        refreshData();
      }
  };

  // --- Neighborhood Handlers ---
  const handleSubmitNeighborhood = async (e: React.FormEvent) => {
      e.preventDefault();
      if (editingNeighborhoodId) {
          await ContentService.updateNeighborhood(editingNeighborhoodId, neighborhoodFormData);
          alert('Quartier mis à jour');
      } else {
          await ContentService.addNeighborhood(neighborhoodFormData as any);
          alert('Quartier ajouté');
      }
      setNeighborhoodFormData({ name: '', representative: '', nextMeeting: '', location: '', description: '' });
      setEditingNeighborhoodId(null);
      refreshData();
  };

  const handleEditNeighborhood = (hood: Neighborhood) => {
      setEditingNeighborhoodId(hood.id);
