          name: hood.name,
          representative: hood.representative,
          nextMeeting: hood.nextMeeting,
          location: hood.location,
          description: hood.description
      });
      window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDeleteNeighborhood = async (id: number) => {
      if(window.confirm('Êtes-vous sûr de vouloir supprimer ce conseil de quartier ?')) {
          await ContentService.deleteNeighborhood(id);
          refreshData();
      }
  };

  // --- Event Handlers ---
  const handleSubmitEvent = async (e: React.FormEvent) => {
      e.preventDefault();
      if (editingEventId) {
          await EventService.update(editingEventId, eventFormData);
          alert('Événement modifié');
      } else {
          await EventService.add(eventFormData);
          alert('Événement ajouté');
      }
      setEventFormData({ title: '', category: 'Culture', description: '', imageUrl: 'https://picsum.photos/800/600', date: '', time: '', location: '' });
      setEditingEventId(null);
      refreshData();
  };

  const handleEditEvent = (event: EventType) => {
      setEditingEventId(event.id);
