          title: event.title,
          category: event.category,
          description: event.description,
          imageUrl: event.imageUrl,
          date: event.date,
          time: event.time,
          location: event.location
      });
      window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleCancelEditEvent = () => {
