  const handleEditAbout = (section: AboutSection) => {
      setEditingAboutId(section.id);
      setAboutFormData({ title: section.title, content: section.content });
      window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDeleteAbout = async (id: number) => {
      if(window.confirm('Supprimer cette section ?')) {
          await ContentService.deleteAbout(id);
          refreshData();
      }
  };

  // --- Status Update Handlers ---
  const handleUpdateReportStatus = async (id: number, status: Report['status']) => {
      await ReportingService.updateStatus(id, status);
      refreshData();
  };

  const handleDeleteReport = async (id: number) => {
      if(window.confirm('Supprimer ce signalement ?')) {
          await ReportingService.delete(id);
          refreshData();
      }
  };

  const handleUpdateMessageStatus = async (id: number, status: Message['status']) => {
      await ContactService.updateStatus(id, status);
      refreshData();
  };

  const handleDeleteMessage = async (id: number) => {
      if(window.confirm('Supprimer ce message ?')) {
          await ContactService.delete(id);
          refreshData();
      }
  };

  const handleUpdateDossierStatus = async (id: string, status: 'Validé' | 'Rejeté' | 'En cours') => {
      await DossierService.updateStatus(id, status);
      refreshData();
  };

  const handleDeleteDossier = async (id: string) => {
      if(window.confirm('Supprimer ce dossier ?')) {
          await DossierService.delete(id);
          refreshData();
      }
  };

  const handleReset = async () => {
      if(window.confirm("Attention : Cela va effacer toutes les données et remettre le site à zéro. Continuer ?")) {
          await ArticleService.reset();
      }
  }

  // --- Badge Components ---
  const StatusBadge = ({ status }: { status: string }) => {
      let colorClass = 'bg-gray-100 text-gray-800';
      if (['Résolu', 'Traité', 'Validé'].includes(status)) colorClass = 'bg-green-100 text-green-800';
      if (['Nouveau', 'En cours'].includes(status)) colorClass = 'bg-yellow-100 text-yellow-800';
      if (['Rejeté'].includes(status)) colorClass = 'bg-red-100 text-red-800';

      return (
          <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${colorClass}`}>
              {status}
          </span>
      );
