const express = require('express');
const router = express.Router();
const contentController = require('../controllers/contentController');
const multer = require('multer');
const path = require('path');
const fs = require('fs');

// Dossier pour les documents
const docDir = 'uploads/documents/';
if (!fs.existsSync(docDir)){
    fs.mkdirSync(docDir, { recursive: true });
}

const storage = multer.diskStorage({
    destination: (req, file, cb) => {
        cb(null, docDir);
    },
    filename: (req, file, cb) => {
        cb(null, Date.now() + '-' + file.originalname);
    }
});

const upload = multer({ 
    storage: storage,
    fileFilter: (req, file, cb) => {
        if (path.extname(file.originalname).toLowerCase() === '.pdf') {
            cb(null, true);
        } else {
            cb(new Error('Seuls les fichiers PDF sont autorisés.'));
        }
    }
});

// Services
router.get('/services', contentController.getServices);

// Documents
router.get('/documents', contentController.getDocuments);
router.post('/documents', upload.single('pdf'), contentController.addDocument);
router.put('/documents/:id', upload.single('pdf'), contentController.updateDocument);
router.delete('/documents/:id', contentController.deleteDocument);

// Procedures & Projects
router.get('/procedures', contentController.getProcedures);
router.get('/projects', contentController.getProjects);

// Neighborhoods
router.get('/neighborhoods', contentController.getNeighborhoods);
router.post('/neighborhoods', contentController.addNeighborhood);
router.put('/neighborhoods/:id', contentController.updateNeighborhood);
router.delete('/neighborhoods/:id', contentController.deleteNeighborhood);

// About
router.get('/about', contentController.getAbout);
router.post('/about', contentController.createAbout);
router.put('/about/:id', contentController.updateAbout);
router.delete('/about/:id', contentController.deleteAbout);

module.exports = router;

