const db = require('../db');

class Content {
    // --- Services ---
    static async getServices() {
        const [rows] = await db.query('SELECT * FROM services');
        return rows;
    }

    // --- Documents ---
    static async getDocuments() {
        const [rows] = await db.query('SELECT * FROM documents ORDER BY id DESC');
        return rows;
    }

    static async addDocument(data) {
        const { name, type, size, category, fileUrl } = data;
        const [result] = await db.query(
            'INSERT INTO documents (name, type, size, category, file_url) VALUES (?, ?, ?, ?, ?)',
            [name, type, size, category, fileUrl]
        );
        return { id: result.insertId, ...data };
    }

    static async updateDocument(id, data) {
        const { name, type, size, category, fileUrl } = data;
        const [result] = await db.query(
            'UPDATE documents SET name = ?, type = ?, size = ?, category = ?, file_url = ? WHERE id = ?',
            [name, type, size, category, fileUrl, id]
        );
        return result.affectedRows > 0;
    }

    static async deleteDocument(id) {
        const [result] = await db.query('DELETE FROM documents WHERE id = ?', [id]);
        return result.affectedRows > 0;
    }

    // --- Procedures & Projects ---
    static async getProcedures() {
        const [rows] = await db.query('SELECT * FROM procedures_list');
        return rows;
    }

    static async getProjects() {
        const [rows] = await db.query('SELECT * FROM projects');
        return rows;
    }

    // --- Neighborhoods ---
    static async getNeighborhoods() {
        const [rows] = await db.query('SELECT * FROM neighborhoods');
        return rows;
    }

    static async addNeighborhood(data) {
        const { name, representative, nextMeeting, location, description } = data;
        const [result] = await db.query(
            'INSERT INTO neighborhoods (name, representative, nextMeeting, location, description) VALUES (?, ?, ?, ?, ?)',
            [name, representative, nextMeeting, location, description]
        );
        return { id: result.insertId, ...data };
    }

    static async updateNeighborhood(id, data) {
        const { name, representative, nextMeeting, location, description } = data;
        const [result] = await db.query(
            'UPDATE neighborhoods SET name = ?, representative = ?, nextMeeting = ?, location = ?, description = ? WHERE id = ?',
            [name, representative, nextMeeting, location, description, id]
        );
        return result.affectedRows > 0;
    }

    static async deleteNeighborhood(id) {
        const [result] = await db.query('DELETE FROM neighborhoods WHERE id = ?', [id]);
        return result.affectedRows > 0;
    }

    // --- About ---
    static async getAbout() {
        try {
            const [rows] = await db.query('SELECT * FROM about_sections');
            return rows;
        } catch (e) {
            console.warn("Table about_sections might not exist", e);
            return [];
        }
    }

    static async createAbout(data) {
        const { title, content } = data;
        const [result] = await db.query(
            'INSERT INTO about_sections (title, content) VALUES (?, ?)',
            [title, content]
        );
        return { id: result.insertId, ...data };
    }

    static async updateAbout(id, data) {
        const { title, content } = data;
        const [result] = await db.query(
            'UPDATE about_sections SET title = ?, content = ? WHERE id = ?', 
            [title, content, id]
        );
        return result.affectedRows > 0;
    }

    static async deleteAbout(id) {
        const [result] = await db.query('DELETE FROM about_sections WHERE id = ?', [id]);
        return result.affectedRows > 0;
    }
}

module.exports = Content;

