const jwt = require('jsonwebtoken');
require('dotenv').config();

const JWT_SECRET = process.env.JWT_SECRET || 'mairie_ziguinchor_secret_key_2024';

module.exports = (req, res, next) => {
    try {
        const authHeader = req.headers.authorization;
        if (!authHeader) {
            return res.status(401).json({ error: "Accès non autorisé. Jeton manquant." });
        }

        const token = authHeader.split(' ')[1]; // Bearer <token>
        const decodedToken = jwt.verify(token, JWT_SECRET);

        // On attache les infos de l'utilisateur à la requête
        req.user = {
            id: decodedToken.userId,
            role: decodedToken.role
        };

        next();
    } catch (error) {
        res.status(401).json({ error: "Session expirée ou jeton invalide." });
    }
};

const User = require('../models/User');
const jwt = require('jsonwebtoken');
require('dotenv').config();

const JWT_SECRET = process.env.JWT_SECRET || 'mairie_ziguinchor_secret_key_2024';

exports.login = async (req, res) => {
    try {
        const { email, password } = req.body;
        const user = await User.findByEmail(email);

        if (!user || user.password !== password) {
            return res.status(401).json({ error: "Email ou mot de passe incorrect." });
        }

        // Génération du jeton JWT (expire dans 24h)
        const token = jwt.sign(
            { userId: user.id, role: user.role },
            JWT_SECRET,
            { expiresIn: '24h' }
        );

        const { password: _, ...safeUser } = user;
        res.json({ ...safeUser, token });
    } catch (e) {
        console.error(e);
        res.status(500).json({ error: "Erreur serveur" });
    }
};

exports.register = async (req, res) => {
    try {
        const { email } = req.body;
        const existingUser = await User.findByEmail(email);
        if (existingUser) {
            return res.status(400).json({ error: "Cet email est déjà utilisé." });
        }

        const newUser = await User.create(req.body);

        // Génération du jeton pour le nouvel utilisateur
        const token = jwt.sign(
            { userId: newUser.id, role: newUser.role },
            JWT_SECRET,
            { expiresIn: '24h' }
        );

        const { password: _, ...safeUser } = newUser;
        res.json({ ...safeUser, token });
    } catch (e) {
        console.error(e);
        res.status(500).json({ error: "Erreur lors de l'inscription" });
    }
};

exports.getAllUsers = async (req, res) => {
    try {
        const users = await User.findAll();
        res.json(users);
    } catch (e) {
        console.error(e);
        res.status(500).json({ error: "Erreur serveur" });
    }
};

export const API_URL = 'http://localhost:5000/api';

// --- Helper pour inclure le token dans les requêtes ---
const getAuthHeaders = () => {
    const stored = localStorage.getItem('mairie_current_user');
    if (stored) {
        const user = JSON.parse(stored);
        if (user.token) {
            return { 'Authorization': `Bearer ${user.token}` };
        }
    }
    return {};
};

const secureFetch = async (url: string, options: RequestInit = {}) => {
    const headers = {
        ...options.headers,
        ...getAuthHeaders(),
    };

    // Si ce n'est pas du FormData, on s'assure d'avoir le Content-Type JSON
    if (!(options.body instanceof FormData) && !headers['Content-Type' as any]) {
        (headers as any)['Content-Type'] = 'application/json';
    }

    const response = await fetch(url, { ...options, headers });

    if (response.status === 401) {
        // Token expiré ou invalide
        localStorage.removeItem('mairie_current_user');
        window.location.href = '/#/login';
    }

    return response;
};

