    create: async (data: any) => (await secureFetch(`${API_URL}/dossiers`, { method: 'POST', body: JSON.stringify(data) })).json(),
    updateStatus: async (id: string, status: string, comment?: string) => secureFetch(`${API_URL}/dossiers/${id}/status`, { method: 'PUT', body: JSON.stringify({ status, comment }) }),
    delete: async (id: string) => secureFetch(`${API_URL}/dossiers/${id}`, { method: 'DELETE' })
};

export const UserService = {
    getAll: async () => (await secureFetch(`${API_URL}/auth/users`)).json(),
    login: async (credentials: any) => {
        const res = await fetch(`${API_URL}/auth/login`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(credentials)
        });
        if (!res.ok) {
            const err = await res.json();
            throw new Error(err.error || 'Erreur de connexion');
        }
        return res.json();
    },
    register: async (userData: any) => {
        const res = await fetch(`${API_URL}/auth/register`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(userData)
        });
        if (!res.ok) {
            const err = await res.json();
            throw new Error(err.error || 'Erreur d\'inscription');
        }
        return res.json();
    }
};

