import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import * as Icons from 'lucide-react';
import { AuthService } from '../services/auth';
import { DossierService } from '../services/api';

const ProcedureForm: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const dossierType = location.state?.dossierType || 'Acte de naissance';
  const [step, setStep] = useState(1);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const user = AuthService.getCurrentUser();

  const [formData, setFormData] = useState({
    firstName: user?.name.split(' ')[0] || '',
    lastName: user?.name.split(' ')[1] || '',
    email: user?.email || '',
    phone: '',
    address: '',
    reason: '',
    specificInfo: ''
  });

  const [files, setFiles] = useState<{name: string, type: string}[]>([]);

  useEffect(() => {
    if (!user) navigate('/login');
  }, [user, navigate]);

  const handleNext = () => setStep(s => s + 1);
  const handlePrev = () => setStep(s => s - 1);

  const handleSubmit = async () => {
    setIsSubmitting(true);
    try {
      const description = `${dossierType} pour ${formData.firstName} ${formData.lastName}. Motif: ${formData.reason}`;
      await DossierService.create({
          userId: user?.id,
          type: dossierType,
          description: description,
          formData: formData
      });
      setStep(5); // Success step
    } catch (e) {
      alert("Erreur lors de la soumission du dossier.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const addFile = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          setFiles([...files, { name: file.name, type: file.type }]);
      }
  };

  const renderStepIcon = (s: number, icon: string) => {
      const Icon = (Icons as any)[icon];
      const isActive = step === s;
      const isDone = step > s;

      return (
          <div className="flex flex-col items-center flex-1">
              <div className={`w-10 h-10 rounded-full flex items-center justify-center transition-all duration-300 ${
                  isActive ? 'bg-primary text-white scale-110 shadow-lg' : 
                  isDone ? 'bg-green-100 text-green-600' : 'bg-gray-100 text-gray-400'
              }`}>
                  {isDone ? <Icons.Check className="w-6 h-6" /> : <Icon className="w-5 h-5" />}
              </div>
              <span className={`text-[10px] mt-2 font-bold uppercase tracking-tight ${isActive ? 'text-primary' : 'text-gray-400'}`}>
                  Étape {s}
              </span>
          </div>
      );
  };

  return (
    <div className="bg-gray-50 min-h-screen py-12 px-4">
      <div className="max-w-3xl mx-auto">

        <div className="mb-12">
            <button onClick={() => navigate(-1)} className="flex items-center text-gray-500 hover:text-primary mb-6 transition">
                <Icons.ArrowLeft className="w-4 h-4 mr-2" /> Retour
            </button>
            <h1 className="text-3xl font-extrabold text-gray-900">{dossierType}</h1>
            <p className="text-gray-500 mt-2">Dépôt de dossier numérique simplifié</p>
        </div>

        {step < 5 && (
            <div className="flex justify-between mb-12 relative">
                <div className="absolute top-5 left-0 right-0 h-0.5 bg-gray-200 -z-10"></div>
                {renderStepIcon(1, 'User')}
                {renderStepIcon(2, 'FileText')}
                {renderStepIcon(3, 'Paperclip')}
                {renderStepIcon(4, 'Eye')}
            </div>
        )}

        <div className="bg-white rounded-3xl shadow-xl overflow-hidden">
            <div className="p-8 md:p-12">

                {/* ETAPE 1 : IDENTITÉ */}
                {step === 1 && (
                    <div className="animate-fade-in-up">
                        <h2 className="text-2xl font-bold mb-8">Informations Personnelles</h2>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className="text-sm font-bold text-gray-700">Prénom</label>
                                <input type="text" className="w-full border rounded-xl p-3 bg-gray-50" value={formData.firstName} onChange={e => setFormData({...formData, firstName: e.target.value})} />
                            </div>
                            <div className="space-y-2">
                                <label className="text-sm font-bold text-gray-700">Nom</label>
                                <input type="text" className="w-full border rounded-xl p-3 bg-gray-50" value={formData.lastName} onChange={e => setFormData({...formData, lastName: e.target.value})} />
                            </div>
                            <div className="space-y-2">
                                <label className="text-sm font-bold text-gray-700">Email</label>
                                <input type="email" className="w-full border rounded-xl p-3 bg-gray-50" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} />
                            </div>
                            <div className="space-y-2">
                                <label className="text-sm font-bold text-gray-700">Téléphone</label>
                                <input type="tel" className="w-full border rounded-xl p-3 focus:ring-primary" placeholder="77 000 00 00" value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} />
                            </div>
                        </div>
                    </div>
                )}

                {/* ETAPE 2 : DETAILS DEMANDE */}
                {step === 2 && (
                    <div className="animate-fade-in-up">
                        <h2 className="text-2xl font-bold mb-8">Détails de la demande</h2>
                        <div className="space-y-6">
                            <div className="space-y-2">
                                <label className="text-sm font-bold text-gray-700">Objet / Motif de la demande</label>
                                <textarea className="w-full border rounded-xl p-3 min-h-[100px]" placeholder="Pourquoi avez-vous besoin de ce document ?" value={formData.reason} onChange={e => setFormData({...formData, reason: e.target.value})}></textarea>
                            </div>
                            <div className="space-y-2">
                                <label className="text-sm font-bold text-gray-700">Informations complémentaires (Dates, lieux...)</label>
                                <textarea className="w-full border rounded-xl p-3 min-h-[100px]" placeholder="Ex: Date de naissance pour un acte, adresse pour un permis..." value={formData.specificInfo} onChange={e => setFormData({...formData, specificInfo: e.target.value})}></textarea>
                            </div>
                        </div>
                    </div>
                )}

                {/* ETAPE 3 : DOCUMENTS */}
                {step === 3 && (
                    <div className="animate-fade-in-up">
                        <h2 className="text-2xl font-bold mb-8">Pièces Justificatives</h2>
                        <p className="text-sm text-gray-500 mb-8">Veuillez joindre une copie lisible de votre CNI et tout document appuyant votre demande.</p>

                        <div className="border-2 border-dashed border-gray-200 rounded-3xl p-12 text-center hover:border-primary transition cursor-pointer relative">
                            <Icons.Upload className="w-12 h-12 text-gray-300 mx-auto mb-4" />
                            <p className="text-gray-600 font-bold">Cliquez ou glissez vos fichiers ici</p>
                            <p className="text-xs text-gray-400 mt-2">PDF, JPG, PNG (Max 5Mo par fichier)</p>
                            <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={addFile} multiple />
                        </div>

                        {files.length > 0 && (
                            <div className="mt-8 space-y-3">
                                {files.map((f, i) => (
                                    <div key={i} className="flex items-center justify-between p-4 bg-gray-50 rounded-2xl border border-gray-100">
                                        <div className="flex items-center">
                                            <Icons.File className="w-5 h-5 text-primary mr-3" />
                                            <span className="text-sm font-medium text-gray-700">{f.name}</span>
                                        </div>
                                        <button onClick={() => setFiles(files.filter((_, idx) => idx !== i))} className="text-red-400 hover:text-red-600">
                                            <Icons.Trash2 className="w-4 h-4" />
                                        </button>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                )}

                {/* ETAPE 4 : RECAPITULATIF */}
                {step === 4 && (
                    <div className="animate-fade-in-up">
                        <h2 className="text-2xl font-bold mb-8">Vérification Finale</h2>
                        <div className="bg-gray-50 rounded-2xl p-6 space-y-6">
                            <div className="grid grid-cols-2 gap-4 text-sm">
                                <div><span className="text-gray-400">Type :</span><p className="font-bold">{dossierType}</p></div>
                                <div><span className="text-gray-400">Demandeur :</span><p className="font-bold">{formData.firstName} {formData.lastName}</p></div>
                            </div>
                            <div className="border-t pt-4">
                                <span className="text-gray-400 text-sm">Description :</span>
                                <p className="text-sm mt-1">{formData.reason}</p>
                            </div>
                            <div className="border-t pt-4">
                                <span className="text-gray-400 text-sm">Fichiers joints :</span>
                                <p className="text-sm mt-1">{files.length} document(s)</p>
                            </div>
                        </div>
                        <div className="mt-8 flex items-start">
                            <input type="checkbox" className="mt-1 h-4 w-4 text-primary rounded border-gray-300" id="agree" />
                            <label htmlFor="agree" className="ml-3 text-sm text-gray-500">
                                Je certifie sur l'honneur que les informations fournies sont exactes et j'accepte les conditions générales d'utilisation du portail citoyen.
                            </label>
                        </div>
                    </div>
                )}

                {/* ETAPE 5 : SUCCESS */}
                {step === 5 && (
                    <div className="text-center py-8 animate-fade-in">
                        <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-8">
                            <Icons.Check className="w-12 h-12" />
                        </div>
                        <h2 className="text-3xl font-extrabold text-gray-900 mb-4">Demande Envoyée !</h2>
                        <p className="text-gray-500 text-lg mb-10 max-w-md mx-auto">
                            Votre dossier a été transmis aux services de la Mairie. Vous recevrez une notification dès qu'une action sera entreprise.
                        </p>
                        <div className="bg-primary/5 p-6 rounded-2xl mb-12 border border-primary/10">
                            <p className="text-xs font-bold text-primary uppercase tracking-widest mb-2">Référence Dossier</p>
                            <p className="text-2xl font-black text-gray-900">ZIG-2024-{Math.floor(1000 + Math.random() * 9000)}</p>
                        </div>
                        <div className="flex flex-col sm:flex-row gap-4 justify-center">
                            <button onClick={() => navigate('/dashboard')} className="bg-primary text-white px-8 py-4 rounded-2xl font-bold hover:bg-green-700 transition shadow-lg">
                                Suivre dans mon espace
                            </button>
                            <button onClick={() => navigate('/')} className="text-gray-600 font-bold px-8 py-4 hover:bg-gray-100 rounded-2xl transition">
                                Retour à l'accueil
                            </button>
                        </div>
                    </div>
                )}

                {/* ACTIONS */}
                {step < 5 && (
                    <div className="mt-12 pt-8 border-t flex justify-between items-center">
                        {step > 1 ? (
                            <button onClick={handlePrev} className="px-6 py-3 font-bold text-gray-500 hover:text-gray-900 flex items-center">
                                <Icons.ChevronLeft className="w-5 h-5 mr-1" /> Précédent
                            </button>
                        ) : <div></div>}

                        {step < 4 ? (
                            <button onClick={handleNext} className="bg-primary text-white px-8 py-4 rounded-2xl font-bold hover:bg-green-700 transition shadow-lg flex items-center">
                                Suivant <Icons.ChevronRight className="w-5 h-5 ml-1" />
                            </button>
                        ) : (
                            <button 
                                onClick={handleSubmit} 
                                disabled={isSubmitting}
                                className="bg-green-600 text-white px-8 py-4 rounded-2xl font-bold hover:bg-green-700 transition shadow-lg flex items-center disabled:opacity-50"
                            >
                                {isSubmitting ? 'Envoi...' : 'Valider et Soumettre'}
                                <Icons.Send className="w-5 h-5 ml-2" />
                            </button>
                        )}
                    </div>
                )}
            </div>
        </div>
      </div>
    </div>
  );
};

export default ProcedureForm;

