import { UserService, DossierService, Dossier } from './api';

export interface User {
  id: string;
  name: string;
  email: string;
  password?: string;
  role?: 'citoyen' | 'employe' | 'admin';
}

const CURRENT_USER_KEY = 'mairie_current_user';

export const AuthService = {
  // Inscription
  register: async (user: Omit<User, 'id'>) => {
    const newUser = await UserService.register(user);
    // Auto login
    localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(newUser));
    return newUser;
  },

  // Connexion
  login: async (email: string, pass: string) => {
    const user = await UserService.login({ email, password: pass });
    localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(user));
    return user;
  },

  // Déconnexion
  logout: () => {
    localStorage.removeItem(CURRENT_USER_KEY);
    window.location.href = '/';
  },

  // Récupérer l'utilisateur courant (reste synchrone car depuis localStorage)
  getCurrentUser: (): User | null => {
    const stored = localStorage.getItem(CURRENT_USER_KEY);
    return stored ? JSON.parse(stored) : null;
  },

  // Récupérer l'historique des dossiers
  // Fix: Use imported Dossier from api.ts which includes all possible status values ('Attente documents', 'Instruction', etc.)
  getHistory: async (): Promise<Dossier[]> => {
    const user = AuthService.getCurrentUser();
    if (!user) return [];
    return await DossierService.getByUser(user.id);
  },

  // Créer un nouveau dossier
  createDossier: async (type: string, description: string) => {
    const user = AuthService.getCurrentUser();
    if (!user) return;
    return await DossierService.create({ userId: user.id, type, description });
  },

  // Exporter les données (Sauvegarde)
  exportData: async () => {
    const user = AuthService.getCurrentUser();
    if (!user) return;

    const history = await AuthService.getHistory();

    const data = {
        userProfile: user,
        dossierHistory: history,
        exportDate: new Date().toISOString()
    };

    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(data, null, 2));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `mairie_export_${user?.name || 'citoyen'}.json`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  }
};

import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import * as Icons from 'lucide-react';
import { AuthService } from '../services/auth';
import { DossierService } from '../services/api';

const ProcedureForm: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const dossierType = location.state?.dossierType || 'Acte de naissance';
  const category = location.state?.category || 'Général';
  const [step, setStep] = useState(1);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const user = AuthService.getCurrentUser();

  const [formData, setFormData] = useState({
    firstName: user?.name.split(' ')[0] || '',
    lastName: user?.name.split(' ')[1] || '',
    email: user?.email || '',
    phone: '',
    address: '',
    reason: '',
    specificInfo: '',
    // Champs sociaux optionnels
    maritalStatus: 'Célibataire',
    childrenCount: '0',
    monthlyIncome: '',
    vulnerabilityType: 'Aucune'
  });

  const [files, setFiles] = useState<{name: string, type: string}[]>([]);

  useEffect(() => {
    if (!user) navigate('/login');
  }, [user, navigate]);

  const handleNext = () => setStep(s => s + 1);
  const handlePrev = () => setStep(s => s - 1);

  const handleSubmit = async () => {
    setIsSubmitting(true);
    try {
      const description = `${dossierType} pour ${formData.firstName} ${formData.lastName}. Catégorie: ${category}`;
      await DossierService.create({
          userId: user?.id,
          type: dossierType,
          description: description,
          formData: formData
      });
      setStep(5); // Success step
    } catch (e) {
      alert("Erreur lors de la soumission du dossier.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const addFile = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          setFiles([...files, { name: file.name, type: file.type }]);
      }
  };

  const renderStepIcon = (s: number, icon: string) => {
      const Icon = (Icons as any)[icon];
      const isActive = step === s;
      const isDone = step > s;

      return (
          <div className="flex flex-col items-center flex-1">
              <div className={`w-10 h-10 rounded-full flex items-center justify-center transition-all duration-300 ${
                  isActive ? 'bg-primary text-white scale-110 shadow-lg' : 
                  isDone ? 'bg-green-100 text-green-600' : 'bg-gray-100 text-gray-400'
              }`}>
                  {isDone ? <Icons.Check className="w-6 h-6" /> : <Icon className="w-5 h-5" />}
              </div>
              <span className={`text-[10px] mt-2 font-bold uppercase tracking-tight ${isActive ? 'text-primary' : 'text-gray-400'}`}>
                  Étape {s}
              </span>
          </div>
      );
  };

  return (
    <div className="bg-gray-50 min-h-screen py-12 px-4">
      <div className="max-w-3xl mx-auto">

        <div className="mb-12">
            <button onClick={() => navigate(-1)} className="flex items-center text-gray-500 hover:text-primary mb-6 transition">
                <Icons.ArrowLeft className="w-4 h-4 mr-2" /> Retour
            </button>
            <div className="flex items-center gap-3">
                <div className="p-3 bg-primary/10 rounded-2xl">
                    {category === 'Social' ? <Icons.Heart className="text-primary w-6 h-6" /> : <Icons.FileText className="text-primary w-6 h-6" />}
                </div>
                <div>
                    <h1 className="text-3xl font-extrabold text-gray-900">{dossierType}</h1>
                    <p className="text-gray-500 text-sm font-bold uppercase tracking-widest">{category}</p>
                </div>
            </div>
        </div>

        {step < 5 && (
            <div className="flex justify-between mb-12 relative">
                <div className="absolute top-5 left-0 right-0 h-0.5 bg-gray-200 -z-10"></div>
                {renderStepIcon(1, 'User')}
                {renderStepIcon(2, 'FileText')}
                {renderStepIcon(3, 'Paperclip')}
                {renderStepIcon(4, 'Eye')}
            </div>
        )}

        <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-gray-100">
            <div className="p-8 md:p-12">

                {/* ETAPE 1 : IDENTITÉ */}
                {step === 1 && (
                    <div className="animate-fade-in-up">
                        <h2 className="text-2xl font-bold mb-8">Informations Personnelles</h2>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className="text-sm font-bold text-gray-700">Prénom</label>
                                <input type="text" className="w-full border rounded-xl p-4 bg-gray-50 focus:ring-2 focus:ring-primary/20 outline-none transition" value={formData.firstName} onChange={e => setFormData({...formData, firstName: e.target.value})} />
                            </div>
                            <div className="space-y-2">
                                <label className="text-sm font-bold text-gray-700">Nom</label>
                                <input type="text" className="w-full border rounded-xl p-4 bg-gray-50 focus:ring-2 focus:ring-primary/20 outline-none transition" value={formData.lastName} onChange={e => setFormData({...formData, lastName: e.target.value})} />
                            </div>
                            <div className="space-y-2">
                                <label className="text-sm font-bold text-gray-700">Email</label>
                                <input type="email" className="w-full border rounded-xl p-4 bg-gray-50 focus:ring-2 focus:ring-primary/20 outline-none transition" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} />
                            </div>
                            <div className="space-y-2">
                                <label className="text-sm font-bold text-gray-700">Téléphone</label>
                                <input type="tel" className="w-full border rounded-xl p-4 focus:ring-2 focus:ring-primary/20 outline-none transition" placeholder="77 000 00 00" value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} />
                            </div>
                        </div>
                    </div>
                )}

                {/* ETAPE 2 : DETAILS DEMANDE (Conditionnel pour Social) */}
                {step === 2 && (
                    <div className="animate-fade-in-up">
                        <h2 className="text-2xl font-bold mb-8">{category === 'Social' ? 'Ma situation sociale' : 'Détails de la demande'}</h2>

                        {category === 'Social' ? (
                            <div className="space-y-6">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div className="space-y-2">
                                        <label className="text-sm font-bold text-gray-700">Situation Matrimoniale</label>
                                        <select className="w-full border rounded-xl p-4" value={formData.maritalStatus} onChange={e => setFormData({...formData, maritalStatus: e.target.value})}>
                                            <option>Célibataire</option>
                                            <option>Marié(e)</option>
                                            <option>Divorcé(e)</option>
                                            <option>Veuf/Veuve</option>
                                        </select>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-sm font-bold text-gray-700">Nombre d'enfants à charge</label>
                                        <input type="number" min="0" className="w-full border rounded-xl p-4" value={formData.childrenCount} onChange={e => setFormData({...formData, childrenCount: e.target.value})} />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-sm font-bold text-gray-700">Revenu mensuel estimé (CFA)</label>
                                        <input type="text" className="w-full border rounded-xl p-4" placeholder="Ex: 50000" value={formData.monthlyIncome} onChange={e => setFormData({...formData, monthlyIncome: e.target.value})} />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-sm font-bold text-gray-700">Type de vulnérabilité</label>
                                        <select className="w-full border rounded-xl p-4" value={formData.vulnerabilityType} onChange={e => setFormData({...formData, vulnerabilityType: e.target.value})}>
                                            <option>Aucune</option>
                                            <option>Maladie chronique</option>
                                            <option>Handicap moteur</option>
                                            <option>Handicap visuel/auditif</option>
                                            <option>Perte d'emploi</option>
                                            <option>Sinistre (Incendie/Inondation)</option>
                                        </select>
                                    </div>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-sm font-bold text-gray-700">Expliquez votre situation et votre besoin</label>
                                    <textarea className="w-full border rounded-xl p-4 min-h-[120px]" placeholder="Détaillez ici les raisons de votre demande d'aide..." value={formData.reason} onChange={e => setFormData({...formData, reason: e.target.value})}></textarea>
                                </div>
                            </div>
                        ) : (
                            <div className="space-y-6">
                                <div className="space-y-2">
                                    <label className="text-sm font-bold text-gray-700">Objet / Motif de la demande</label>
                                    <textarea className="w-full border rounded-xl p-4 min-h-[100px]" placeholder="Pourquoi avez-vous besoin de ce document ?" value={formData.reason} onChange={e => setFormData({...formData, reason: e.target.value})}></textarea>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-sm font-bold text-gray-700">Informations complémentaires (Dates, lieux...)</label>
                                    <textarea className="w-full border rounded-xl p-4 min-h-[100px]" placeholder="Ex: Date de naissance pour un acte, adresse pour un permis..." value={formData.specificInfo} onChange={e => setFormData({...formData, specificInfo: e.target.value})}></textarea>
                                </div>
                            </div>
                        )}
                    </div>
                )}

                {/* ETAPE 3 : DOCUMENTS */}
                {step === 3 && (
                    <div className="animate-fade-in-up">
                        <h2 className="text-2xl font-bold mb-8">Pièces Justificatives</h2>
                        <p className="text-sm text-gray-500 mb-8">
                            {category === 'Social' 
                                ? 'Veuillez joindre votre CNI, votre certificat de résidence et tout justificatif de revenus ou médical.'
                                : 'Veuillez joindre une copie lisible de votre CNI et tout document appuyant votre demande.'}
                        </p>

                        <div className="border-2 border-dashed border-gray-200 rounded-3xl p-12 text-center hover:border-primary transition cursor-pointer relative bg-gray-50">
                            <Icons.Upload className="w-12 h-12 text-gray-300 mx-auto mb-4" />
                            <p className="text-gray-600 font-bold">Cliquez ou glissez vos fichiers ici</p>
                            <p className="text-xs text-gray-400 mt-2">PDF, JPG, PNG (Max 5Mo par fichier)</p>
                            <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={addFile} multiple />
                        </div>

                        {files.length > 0 && (
                            <div className="mt-8 space-y-3">
                                {files.map((f, i) => (
                                    <div key={i} className="flex items-center justify-between p-4 bg-gray-50 rounded-2xl border border-gray-100">
                                        <div className="flex items-center">
                                            <Icons.File className="w-5 h-5 text-primary mr-3" />
                                            <span className="text-sm font-medium text-gray-700">{f.name}</span>
                                        </div>
                                        <button onClick={() => setFiles(files.filter((_, idx) => idx !== i))} className="text-red-400 hover:text-red-600">
                                            <Icons.Trash2 className="w-4 h-4" />
                                        </button>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                )}

                {/* ETAPE 4 : RECAPITULATIF */}
                {step === 4 && (
                    <div className="animate-fade-in-up">
                        <h2 className="text-2xl font-bold mb-8">Vérification Finale</h2>
                        <div className="bg-gray-50 rounded-2xl p-6 space-y-6">
                            <div className="grid grid-cols-2 gap-4 text-sm">
                                <div><span className="text-gray-400 font-bold uppercase text-[10px]">Type :</span><p className="font-bold">{dossierType}</p></div>
                                <div><span className="text-gray-400 font-bold uppercase text-[10px]">Demandeur :</span><p className="font-bold">{formData.firstName} {formData.lastName}</p></div>
                                {category === 'Social' && (
                                    <>
                                        <div><span className="text-gray-400 font-bold uppercase text-[10px]">Sit. Familiale :</span><p className="font-bold">{formData.maritalStatus} ({formData.childrenCount} enf.)</p></div>
                                        <div><span className="text-gray-400 font-bold uppercase text-[10px]">Vulnérabilité :</span><p className="font-bold">{formData.vulnerabilityType}</p></div>
                                    </>
                                )}
                            </div>
                            <div className="border-t pt-4">
                                <span className="text-gray-400 font-bold uppercase text-[10px]">Motif :</span>
                                <p className="text-sm mt-1">{formData.reason}</p>
                            </div>
                            <div className="border-t pt-4">
                                <span className="text-gray-400 font-bold uppercase text-[10px]">Fichiers joints :</span>
                                <p className="text-sm mt-1">{files.length} document(s)</p>
                            </div>
                        </div>
                        <div className="mt-8 flex items-start bg-amber-50 p-4 rounded-xl border border-amber-100">
                            <input type="checkbox" className="mt-1 h-5 w-5 text-primary rounded border-gray-300" id="agree" />
                            <label htmlFor="agree" className="ml-3 text-xs text-amber-800 font-medium">
                                Je certifie sur l'honneur que les informations fournies sont exactes. Je comprends que toute fausse déclaration peut entraîner le rejet de ma demande sociale.
                            </label>
                        </div>
                    </div>
                )}

                {/* ETAPE 5 : SUCCESS */}
                {step === 5 && (
                    <div className="text-center py-8 animate-fade-in">
                        <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-8">
                            <Icons.Check className="w-12 h-12" />
                        </div>
                        <h2 className="text-3xl font-extrabold text-gray-900 mb-4">Demande Sociale Enregistrée !</h2>
                        <p className="text-gray-500 text-lg mb-10 max-w-md mx-auto">
                            Votre dossier a été transmis au service d'Action Sociale (CCAS). Un travailleur social étudiera votre demande sous peu.
                        </p>
                        <div className="bg-primary/5 p-6 rounded-2xl mb-12 border border-primary/10">
                            <p className="text-xs font-bold text-primary uppercase tracking-widest mb-2">Référence Dossier Social</p>
                            <p className="text-3xl font-black text-gray-900 tracking-tighter">SOC-2024-{Math.floor(1000 + Math.random() * 9000)}</p>
                        </div>
                        <div className="flex flex-col sm:flex-row gap-4 justify-center">
                            <button onClick={() => navigate('/dashboard')} className="bg-primary text-white px-10 py-4 rounded-2xl font-black hover:bg-green-700 transition shadow-lg">
                                Suivre mon dossier
                            </button>
                            <button onClick={() => navigate('/')} className="text-gray-600 font-bold px-8 py-4 hover:bg-gray-100 rounded-2xl transition">
                                Retour à l'accueil
                            </button>
                        </div>
                    </div>
                )}

                {/* ACTIONS */}
                {step < 5 && (
                    <div className="mt-12 pt-8 border-t border-gray-100 flex justify-between items-center">
                        {step > 1 ? (
                            <button onClick={handlePrev} className="px-6 py-3 font-bold text-gray-400 hover:text-gray-900 flex items-center transition">
                                <Icons.ChevronLeft className="w-5 h-5 mr-1" /> Précédent
                            </button>
                        ) : <div></div>}

                        {step < 4 ? (
                            <button onClick={handleNext} className="bg-primary text-white px-10 py-4 rounded-2xl font-black hover:bg-green-700 transition shadow-lg flex items-center">
                                Continuer <Icons.ChevronRight className="w-5 h-5 ml-1" />
                            </button>
                        ) : (
                            <button 
                                onClick={handleSubmit} 
                                disabled={isSubmitting}
                                className="bg-green-600 text-white px-10 py-4 rounded-2xl font-black hover:bg-green-700 transition shadow-xl flex items-center disabled:opacity-50"
                            >
                                {isSubmitting ? 'Envoi...' : 'Valider et Soumettre'}
                                <Icons.Send className="w-5 h-5 ml-2" />
                            </button>
                        )}
                    </div>
                )}
            </div>
        </div>
      </div>
    </div>
  );
};

export default ProcedureForm;

import React, { useEffect, useState } from 'react';
import { AuthService, User } from '../services/auth';
import { DossierService, Dossier } from '../services/api';
import { useNavigate, useLocation } from 'react-router-dom';
import * as Icons from 'lucide-react';

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [user, setUser] = useState<User | null>(null);
  const [history, setHistory] = useState<Dossier[]>([]);
  const [selectedDossier, setSelectedDossier] = useState<Dossier | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const currentUser = AuthService.getCurrentUser();
    if (!currentUser) {
      navigate('/login');
      return;
    }
    setUser(currentUser);
    refreshHistory(currentUser.id);
  }, [navigate]);

  const refreshHistory = async (userId: string) => {
      setLoading(true);
      try {
          const docs = await DossierService.getByUser(userId);
          setHistory(docs);
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  const getStatusInfo = (status: string) => {
      switch(status) {
          case 'Validé': return { color: 'bg-green-100 text-green-700', icon: Icons.CheckCircle };
          case 'Rejeté': return { color: 'bg-red-100 text-red-700', icon: Icons.XCircle };
          case 'Attente documents': return { color: 'bg-orange-100 text-orange-700', icon: Icons.AlertTriangle };
          case 'Instruction': return { color: 'bg-blue-100 text-blue-700', icon: Icons.Eye };
          default: return { color: 'bg-yellow-100 text-yellow-700', icon: Icons.Clock };
      }
  };

  if (!user) return null;

  return (
    <div className="min-h-screen bg-gray-50 py-12">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Header Profil */}
        <div className="bg-white rounded-3xl shadow-sm p-8 mb-12 flex flex-col md:flex-row items-center justify-between border border-gray-100">
          <div className="flex items-center mb-6 md:mb-0">
            <div className="h-20 w-20 bg-primary text-white rounded-2xl flex items-center justify-center text-3xl font-black shadow-lg shadow-primary/20 mr-6">
              {user.name.charAt(0)}
            </div>
            <div>
              <h1 className="text-2xl font-black text-gray-900">Espace Citoyen</h1>
              <p className="text-gray-500 font-medium">Bienvenue, <span className="text-primary">{user.name}</span></p>
            </div>
          </div>
          <div className="flex gap-4">
             <button onClick={() => AuthService.exportData()} className="flex items-center px-5 py-3 bg-gray-50 text-gray-700 rounded-xl font-bold hover:bg-gray-100 transition border border-gray-100">
              <Icons.Download className="w-5 h-5 mr-2" /> Exporter
            </button>
            <button onClick={() => AuthService.logout()} className="flex items-center px-5 py-3 bg-red-50 text-red-600 rounded-xl font-bold hover:bg-red-100 transition">
              <Icons.LogOut className="w-5 h-5 mr-2" /> Quitter
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">

          {/* Liste des Dossiers */}
          <div className="lg:col-span-2 space-y-6">
             <div className="flex items-center justify-between mb-8">
                <h2 className="text-2xl font-black text-gray-900 flex items-center">
                    <Icons.FileText className="w-7 h-7 mr-3 text-primary" />
                    Mes Démarches
                </h2>
                <div className="flex gap-3">
                    <button 
                        onClick={() => navigate('/social')}
                        className="bg-purple-600 text-white px-5 py-3 rounded-xl font-bold hover:bg-purple-700 transition shadow-lg flex items-center"
                    >
                        <Icons.Heart className="w-5 h-5 mr-2" />
                        Aide Sociale
                    </button>
                    <button 
                        onClick={() => navigate('/demarches')}
                        className="bg-primary text-white px-5 py-3 rounded-xl font-bold hover:bg-green-700 transition shadow-lg flex items-center"
                    >
                        <Icons.PlusCircle className="w-5 h-5 mr-2" />
                        Nouveau Dossier
                    </button>
                </div>
             </div>

             {loading ? (
                 <div className="bg-white p-20 rounded-3xl border border-gray-100 text-center">
                     <div className="animate-spin w-10 h-10 border-4 border-primary border-t-transparent rounded-full mx-auto"></div>
                     <p className="mt-4 text-gray-400 font-bold">Synchronisation de vos dossiers...</p>
                 </div>
             ) : history.length > 0 ? (
                 <div className="space-y-4">
                    {history.map((item) => {
                        const s = getStatusInfo(item.status);
                        const isSelected = selectedDossier?.id === item.id;
                        const isSocial = item.id.startsWith('SOC') || item.type.toLowerCase().includes('aide') || item.type.toLowerCase().includes('social');

                        return (
                            <div 
                                key={item.id} 
                                onClick={() => setSelectedDossier(item)}
                                className={`bg-white p-6 rounded-2xl border transition-all duration-300 cursor-pointer hover:shadow-xl ${
                                    isSelected ? 'border-primary ring-4 ring-primary/5 shadow-xl transform scale-[1.02]' : 'border-gray-100'
                                }`}
                            >
                                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                                    <div className="flex items-center">
                                        <div className={`p-3 rounded-xl mr-4 ${isSocial ? 'bg-purple-50 text-purple-600' : s.color}`}>
                                            {isSocial ? <Icons.Heart className="w-6 h-6" /> : <s.icon className="w-6 h-6" />}
                                        </div>
                                        <div>
                                            <h3 className="font-black text-gray-900 text-lg">{item.type}</h3>
                                            <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mt-1">Référence : {item.id}</p>
                                        </div>
                                    </div>
                                    <div className="flex items-center justify-between sm:flex-col sm:items-end">
                                        <span className={`px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-widest ${s.color}`}>
                                            {item.status}
                                        </span>
                                        <p className="text-xs text-gray-400 font-bold mt-2">Dépôt le {new Date(item.date).toLocaleDateString()}</p>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                 </div>
             ) : (
                 <div className="bg-white p-20 rounded-3xl border-2 border-dashed border-gray-200 text-center">
                     <Icons.FolderSearch className="w-16 h-16 text-gray-200 mx-auto mb-6" />
                     <h3 className="text-xl font-bold text-gray-900">Aucun dossier trouvé</h3>
                     <p className="text-gray-400 mt-2 max-w-xs mx-auto">Commencez votre première démarche en ligne dès aujourd'hui.</p>
                 </div>
             )}
          </div>

          {/* Détails du Dossier Sélectionné */}
